from pathlib import Path
import html, json, re, zipfile

ROOT=Path(__file__).resolve().parent.parent
OUT=ROOT/'outputs'/'security-foundations'
OUT.mkdir(parents=True,exist_ok=True)
chapters=[]
def p(s): return '<p>'+s+'</p>'
def actions(*items):
    return '<ol class="actions">'+''.join('<li>'+item+'</li>' for item in items)+'</ol>'
def settings(*pairs):
    return '<dl class="settings">'+''.join('<div><dt>'+field+'</dt><dd>'+value+'</dd></div>' for field,value in pairs)+'</dl>'
def check(s):
    return '<p class="result"><strong>Check:</strong> '+s+'</p>'
def ul(*items): return '<ul>'+''.join('<li>'+i+'</li>' for i in items)+'</ul>'
def code(s,where='Ubuntu guest • Bash'):
    return '<div class="command"><div class="terminal-label">'+html.escape(where)+'</div><pre><code>'+html.escape(s.strip())+'</code></pre></div>'
def note(s): return '<aside class="note">'+s+'</aside>'
def step(title,body): return '<section class="step"><h3>'+title+'</h3>'+body+'</section>'
def refs(*pairs): return '<h3>Source documentation</h3>'+ul(*['<a href="'+u+'">'+t+'</a>' for t,u in pairs])
def add(n,title,phase,concept,run,steps,proof,questions,fix,stretch,links=[]):
    chapters.append(dict(n=n,title=title,phase=phase,concept=concept,run=run,steps=steps,proof=proof,questions=questions,fix=fix,stretch=stretch,links=links))

add(1,'Prepare the laptop and your learning system','Foundations',
'A host is the real computer. A guest is an operating system inside a virtual machine (VM). The hypervisor allocates CPU, memory, disks, and networks to guests. A VM is useful isolation, but sharing folders, networks, and credentials can cross that boundary. Your first security control is knowing which computer you are changing.',
'Windows laptop only. No VM yet.',[
step('1. Make a baseline record',(actions('On the laptop, open Start → Settings → System → About.', 'Record the Windows edition, installed RAM, processor, and device name.', 'Press Ctrl+Shift+Esc → Performance → CPU; record whether Virtualization says Enabled.', 'Open File Explorer → This PC and record free space.') + p('Aim for at least 250 GB free before installing the course VMs.') + p('Close unnecessary applications during labs.'))),
step('2. Protect the host',(actions('Back up personal work before changing virtualization settings.', 'Apply Windows Update and restart.', 'Open Windows Security and confirm antivirus and firewall are on.', 'If device encryption or BitLocker is enabled, verify you can retrieve its recovery key before entering BIOS.', 'Keep the key private.', 'Use AC power and ventilation; save work and shut guests down cleanly before an expected power interruption.'))),
step('3. Create the notebook',(actions('Open File Explorer.', 'Create C:\\CyberLab and subfolders ISOs, VMs, Evidence, Exports, and Private.') + p('Evidence is for sanitized learning results; Private is for anything containing passwords, keys, or sensitive configuration.') + actions('Use a password manager for credentials.', 'Do not publish Private or VM disks.'))+code("New-Item -ItemType Directory -Force -Path C:\\CyberLab\\ISOs,C:\\CyberLab\\VMs,C:\\CyberLab\\Evidence,C:\\CyberLab\\Exports,C:\\CyberLab\\Private\nNew-Item -ItemType Directory -Force -Path C:\\CyberLab\\Evidence\\week01",'HOST • ordinary PowerShell')+(actions('For each week, create a matching Evidence\\weekNN directory.', 'Use the report template in this course.', 'Write the purpose of each command before executing it.') + p('Afterward record expected versus actual results.'))),
step('4. Check Hyper-V eligibility',(p('Search Start for PowerShell, right-click Windows PowerShell → Run as administrator.') + p('The title should say Administrator.') + p('Run:'))+code('systeminfo.exe\nGet-WindowsOptionalFeature -Online -FeatureName Microsoft-Hyper-V-All','HOST • administrator PowerShell')+(p('Windows 11 Pro supports Hyper-V; Home does not. Near the end of systeminfo, the virtualization requirements should be Yes, or it may say a hypervisor is already detected.') + actions('If virtualization is disabled, open firmware setup using the instructions for your model (the key varies by manufacturer).', 'Enable Intel VT-x or AMD-V, sometimes called SVM Mode.') + p('Menu wording varies.') + actions('Do not change storage mode, boot mode, or unrelated firmware settings.', 'If the setting is locked, get help from the laptop administrator.'))),
step('5. Enable Hyper-V',(actions('Save all work.', 'Run the following once, then restart from the Start menu when prompted.', 'Do not use it if Hyper-V is already enabled.'))+code('Enable-WindowsOptionalFeature -Online -FeatureName Microsoft-Hyper-V -All','HOST • administrator PowerShell')+(actions('After restarting, search Start for Hyper-V Manager.', 'Open it and select the local computer.', 'If it is missing, check the Windows edition and feature state.', 'Do not install multiple hypervisors to work around an unexplained error.'))),
step('6. Establish the scope',(actions('Write: “My targets are the named course VMs and my mentor-provided cloud resource group only.” Never scan an employer, ISP, university, public address range, or household device.', 'Use harmless test events and dummy data; this course does not require live malware.', 'Agree on a regular review time with your mentor in both local time zones.')))],
['Host baseline and virtualization screenshot, with identifiers redacted','Working Hyper-V Manager','A one-page scope and learning notebook'],['How is a checkpoint different from a backup?','Which changes in this week affected the real laptop?'],
'Hyper-V missing: confirm Pro edition, reboot, then inspect feature state. A firmware problem is a host problem; reinstalling guest operating systems will not fix it.',
'Spend up to two extra hours exploring Task Manager and Resource Monitor. Explain CPU load versus memory pressure.',
[('Hyper-V requirements','https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/host-hardware-requirements'),('Install Hyper-V','https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/get-started/install-hyper-v')])

add(2,'Build your first Linux VM','Foundations',
'An ISO is installation media, similar to a virtual DVD. A VHDX is a guest disk stored as a host file. A dynamically expanding disk grows as data is written, up to its configured limit. Ubuntu Server has a terminal rather than a desktop; this reduces memory use and teaches the underlying system.',
'UBU01 only: 2 vCPU, 2 GB fixed RAM, 40 GB dynamic VHDX.',[
step('1. Download the right installer',(p('From the Ubuntu 24.04 release directory linked below, download the current 24.04.x live-server amd64 ISO into C:\\CyberLab\\ISOs.') + p('The amd64 image supports compatible 64-bit Intel and AMD processors. This walkthrough does not cover ARM hosts.') + actions('Record the exact filename, date, download URL, and version in versions.txt.', 'Download SHA256SUMS from the same HTTPS release directory.', 'In PowerShell run Get-FileHash with the exact local ISO path and compare every hash character with its SHA256SUMS entry.') + p('A hash comparison detects corruption; a signed checksum verified with a trusted signing key adds stronger origin verification.'))),
step('2. Create UBU01',p('In Hyper-V Manager, select the host and open <strong>New → Virtual Machine</strong>.')+
settings(('Name','UBU01'),('Location',r'C:\CyberLab\VMs'),('Generation','Generation 2'),('Startup memory','2048 MB; clear Dynamic Memory'),('Connection','Default Switch, temporarily for installation and updates'),('Virtual disk','New 40 GB dynamically expanding VHDX'),('Installation media','Choose a bootable image file and select your verified Ubuntu ISO.'))+
actions('Finish the wizard. Right-click UBU01 and open <strong>Settings → Processor</strong>. Set the processor count to 2.','Open <strong>Security</strong>. Keep Secure Boot enabled and select <strong>Microsoft UEFI Certificate Authority</strong> for the Linux guest.')),
step('3. Install into the virtual disk',(actions('Connect → Start.', 'Press a key if prompted to boot the DVD.', 'In the Ubuntu installer choose English, the correct keyboard, Ubuntu Server, and automatic DHCP networking.', 'Leave proxy blank unless your network requires one.', 'Accept a working mirror.', 'Choose “Use an entire disk” only after verifying this is the 40 GB virtual disk inside UBU01.', 'For simplicity clear LVM if offered.') + check('Confirm the guest-disk changes.') + actions('Enter your name, server name ubu01, username learner, and a unique password.', 'Enable Install OpenSSH server.', 'Skip optional featured snaps and Ubuntu Pro enrollment.', 'Finish installation, eject the ISO through VM Settings → DVD Drive → None if needed, and reboot.'))),
step('4. Learn the terminal',(p('Sign in as learner.') + p('Password typing shows no characters; this is normal. Commands are case-sensitive.') + p('Type one line at a time.') + p('The # symbol starts a comment; $ shown in websites is often a prompt, not part of the command.'))+code('whoami\nhostname\npwd\nip -br address\nfree -h\ndf -h /\ncat /etc/os-release')+(check('Expect learner, ubu01, your home directory, an IPv4 address, about 2 GB memory, and Ubuntu 24.04.') + p('Record actual values rather than copying expected output.'))),
step('5. Update and prepare tools',code('sudo apt update\nsudo apt upgrade\nsudo apt install openssh-server curl wget nano git jq dnsutils tcpdump nmap nginx ufw rsyslog auditd openssl python3\nsudo systemctl enable --now ssh\nsudo systemctl status ssh --no-pager')+(p('sudo runs a command with administrator privilege and may ask for your learner password. apt update refreshes package information; apt upgrade installs newer packages.') + actions('Read prompts before accepting.', 'If a reboot is needed, run sudo reboot and sign back in.') + p('Tool downloads require internet; the reading material does not.'))),
step('6. Save a clean recovery point',(actions('In the guest run sudo poweroff.', 'In Hyper-V Manager verify Off, then right-click UBU01 → Checkpoint.') + p('Rename it w02-clean-linux. A checkpoint depends on the VM’s disk chain; it is not an independent backup.') + actions('Start the VM and verify you can log in.', 'Keep only a few named checkpoints; delete old ones through Hyper-V Manager, never by deleting AVHDX files in Explorer.')))],
['Version and hash record','Guest identity, IP, memory, disk, and SSH service output','Clean Linux checkpoint and successful reboot'],['What is the difference between the ISO and VHDX?','Why does sudo ask for your password?'],
'No boot: check DVD boot order and Linux Secure Boot template. No address: confirm Default Switch and DHCP. apt lock: wait for the updater to finish; do not delete lock files. SSH status exits with q if it opens a pager.',
'Use man ls and man systemctl. Practice searching with / and exiting with q.',
[('Ubuntu 24.04 installation media','https://releases.ubuntu.com/24.04/'),('Ubuntu installation','https://ubuntu.com/server/docs/tutorial/basic-installation/')])

add(3,'Build an isolated network and trace packets','Foundations',
'An IP address identifies an interface; a subnet tells it which destinations are local. ARP maps local IPv4 addresses to Ethernet addresses. DNS maps names to addresses. A gateway forwards traffic beyond a subnet. TCP ports identify services. A private Hyper-V switch connects guests only; it does not connect the host or internet.',
'UBU01 + newly installed UBU02, each 2 GB. Default Switch is used only for installation or updates; CyberLab-Private is the exercise network.',[
step('1. Create the exercise switch',code('New-VMSwitch -Name "CyberLab-Private" -SwitchType Private\nGet-VMSwitch | Format-Table Name,SwitchType','HOST • administrator PowerShell')+(p('Run New-VMSwitch only if that name does not already exist.') + p('Private is intentional.') + p('Do not substitute External, Internal, or Default Switch during isolated exercises.') + p('A NAT switch provides outbound access and is not isolation.'))),
step('2. Install a second machine',(actions('Repeat Week 2’s VM wizard and Ubuntu installation with name UBU02, guest hostname ubu02, 2 GB RAM, 2 vCPU, and 40 GB disk.', 'Use a fresh install, not a copy of an enrolled or running VM.') + p('Complete the same update and package steps.') + actions('Shut down both guests.', 'In each VM’s Settings → Network Adapter, choose CyberLab-Private.') + p('Each guest must have exactly one network adapter for these exercises.'))),
step('3. Give UBU01 a fixed address',(actions('Start UBU01 and use the Hyper-V console.', 'Run ip -br link and note the Ethernet interface, often eth0.') + p('The example below assumes eth0; substitute the observed interface name if different.') + actions('Run ls /etc/netplan.', 'Back up the existing YAML file(s) into ~/netplan-backup, then move the original YAML files out of /etc/netplan so only your new configuration controls the interface.') + p('These are guest commands.'))+code('mkdir -p ~/netplan-backup\nsudo mv /etc/netplan/*.yaml ~/netplan-backup/\nsudo nano /etc/netplan/01-lab.yaml')+p('Type this file with spaces, not tabs. nano: Ctrl+O, Enter saves; Ctrl+X exits.')+code('network:\n  version: 2\n  ethernets:\n    eth0:\n      dhcp4: false\n      dhcp6: false\n      accept-ra: false\n      addresses: [10.77.0.11/24]','UBU01 • /etc/netplan/01-lab.yaml')+code('sudo chmod 600 /etc/netplan/01-lab.yaml\nsudo netplan generate\nsudo netplan try')+(check('Confirm within the displayed timeout after checking the console still works.') + p('Run ip -br address and ip route.') + check('Expect 10.77.0.11/24 and a connected 10.77.0.0/24 route, with no default route.') + p('No gateway or DNS server is configured on this private segment.'))),
step('4. Configure UBU02 and prove isolation',p('Repeat the previous step inside UBU02, using 10.77.0.12/24. Then on UBU02 run:')+code('ping -c 3 10.77.0.11\nip neigh\nip route\nping -c 1 -W 2 1.1.1.1')+(check('The peer ping should work.') + p('The internet ping should fail with network unreachable or no reply; also confirm no default route and the Private switch on the host. A failed ping alone is not sufficient proof of isolation.') + p('Document both switch settings and routing tables.'))),
step('5. Watch a real conversation',(actions('On UBU01 start a packet capture; leave it running.', 'On UBU02 run the ping and HTTP request below.', 'Then return to UBU01 and press Ctrl+C.'))+code('sudo tcpdump -ni eth0 -w /tmp/week03.pcap "arp or icmp or tcp port 80"','UBU01 • Bash; replace eth0 if needed')+code('ping -c 3 10.77.0.11\ncurl -I http://10.77.0.11','UBU02 • Bash')+code('sudo tcpdump -nn -r /tmp/week03.pcap | head -40','UBU01 • Bash')+(actions('If nginx is stopped, start it with sudo systemctl start nginx and repeat.', 'Identify source/destination IPs, ports, and TCP SYN/SYN-ACK/ACK.') + p('The capture sees traffic involving UBU01, not automatically all traffic on the virtual switch.'))),
step('6. Understand update mode',(p('To update a Linux VM later: shut it down, connect its only adapter to Default Switch, and in its console change the netplan interface block to dhcp4: true, removing addresses.') + actions('Apply with netplan try, then check IP, default route, DNS resolution, and apt update.', 'After updates, shut down, reconnect CyberLab-Private, restore that VM’s static address file, apply and verify isolation again.', 'Never take deliberately vulnerable services into update mode while they are listening.')))],
['Address plan and diagram','Peer connectivity plus three isolation checks','PCAP with an annotated TCP conversation'],['Why does peer HTTP work without DNS?','Why is Default Switch unsuitable for the isolated test network?'],
'Peer timeout: check both switch names, unique addresses, /24 masks, and guest firewall. Internet working in exercise mode: stop the exercise and inspect additional adapters, gateways, and host routing. Incorrect YAML: netplan generate identifies the line.',
'Calculate network, broadcast, and usable host addresses for 10.77.0.0/24. Inspect packet capture text for Ethernet versus IP addressing.',
[('Hyper-V networking','https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/plan/plan-hyper-v-networking-in-windows-server'),('Netplan examples','https://netplan.readthedocs.io/en/stable/examples/')])

add(4,'Linux files, users, and least privilege','Foundations',
'Linux permissions distinguish owner, group, and everyone else. Read, write, and execute mean different things on files and directories. Least privilege means giving a task only the access it needs. A service account, a human user, and root serve different purposes.',
'UBU01 + UBU02 on CyberLab-Private. Wazuh and Windows VMs do not exist yet.',[
step('1. Navigate without guessing',code('pwd\nls -la\nmkdir -p ~/lab/week04\ncd ~/lab/week04\nprintf "security notes\\n" > notes.txt\ncat notes.txt\ncp notes.txt notes-backup.txt\nls -l')+(p('The tilde means your home directory; > replaces file contents, while >> appends.') + actions('Before using either, read the destination carefully.', 'Never practice destructive commands against /, /etc, or personal files.'))),
step('2. Create a controlled access boundary',code('sudo addgroup labreaders\nsudo adduser analyst\nsudo usermod -aG labreaders analyst\nsudo mkdir -p /srv/labshare\nsudo chown root:labreaders /srv/labshare\nsudo chmod 750 /srv/labshare\nprintf "dummy case data\\n" | sudo tee /srv/labshare/case.txt\nsudo chown root:labreaders /srv/labshare/case.txt\nsudo chmod 640 /srv/labshare/case.txt')+(p('Use a unique lab password for analyst.') + p('The group may read the file but not change it; other users cannot enter the directory. tee writes standard input to a file with the specified privilege.'))),
step('3. Test allowed and denied operations',code('sudo -u analyst cat /srv/labshare/case.txt\nsudo -u analyst sh -c "echo changed >> /srv/labshare/case.txt"\nsudo -u nobody cat /srv/labshare/case.txt\nnamei -l /srv/labshare/case.txt')+(check('Expect the first read to succeed, the write to fail, and nobody’s read to fail.') + p('Save all three results.') + p('A security control is unproven until both its allowed and denied cases are tested.'))),
step('4. Inspect process identity',code('ps -eo user,pid,ppid,comm --sort=user | head -30\nsystemctl status nginx --no-pager\nsudo ss -lntp\nid learner\nsudo -l')+(actions('Find nginx’s worker user and listening socket.', 'Explain why a process may need a privileged startup operation but perform routine work under a limited identity.', 'Do not add analyst to sudo.'))),
step('5. Break and repair one permission',code('sudo chmod 600 /srv/labshare/case.txt\nsudo -u analyst cat /srv/labshare/case.txt\nsudo chmod 640 /srv/labshare/case.txt\nsudo -u analyst cat /srv/labshare/case.txt')+(actions('Write a change record with the symptom, reason, correction, and verification.', 'Keep the sample directory for later file-integrity exercises.', 'Do not “fix” access by using chmod 777.')))],
['Permission matrix with successful and denied tests','Process/user/socket map','Repair record'],['Why can readable files still be inaccessible through a directory?','How is sudo different from being a member of labreaders?'],
'A newly added group may not appear in an existing interactive session; sign out/in. sudo -u starts a fresh identity for these checks. Inspect every parent directory with namei before widening permissions.',
'Use setfacl/getfacl after installing acl in update mode; compare an explicit user ACL with group permissions.',
[('Ubuntu user management','https://documentation.ubuntu.com/server/how-to/security/user-management/')])

add(5,'Services, logs, and recoverable configuration','Systems',
'A service manager starts and supervises long-running programs. Configuration describes intended behavior; sockets and requests reveal actual behavior. Logs are records of events, not complete truth. Accurate time and a known collection path make those records useful.',
'UBU01 + UBU02 on private switch.',[
step('1. Make the web service observable',code('sudo systemctl enable --now nginx\nsudo nginx -t\ncurl -I http://127.0.0.1\nsudo ss -lntp\nsudo journalctl -u nginx --since "15 minutes ago" --no-pager','UBU01 • Bash')+code('curl -I http://10.77.0.11','UBU02 • Bash')+(p('127.0.0.1 is loopback: the current machine. A local request succeeding does not prove a remote request will work.') + p('Record HTTP status, process, and port.'))),
step('2. Produce a harmless log event',code('logger -t cyberlab "week05 baseline event"\nsudo journalctl -t cyberlab --since "5 minutes ago" --no-pager\ndate -u\ntimedatectl')+(actions('Record UTC timestamps in evidence.', 'In private mode time synchronization through the internet is unavailable; compare guest clocks with the host and correct large differences through a controlled update session.', 'Explain local display time versus UTC.'))),
step('3. Change nginx deliberately',(p('Back up the site file, then open it.') + p('Inside its existing server block add the header below; do not replace the entire configuration.'))+code('sudo cp /etc/nginx/sites-available/default /etc/nginx/sites-available/default.w05-backup\nsudo nano /etc/nginx/sites-available/default')+code('add_header X-Lab-Owner "learner" always;','UBU01 • add inside nginx server block')+code('sudo nginx -t\nsudo systemctl reload nginx\ncurl -I http://127.0.0.1')+(p('Only reload if the syntax check succeeds.') + check('Expect the X-Lab-Owner header.') + p('Note that a reload can preserve service availability while adopting valid configuration.'))),
step('4. Diagnose a controlled outage',code('sudo systemctl stop nginx','UBU01 • Bash')+(p('From UBU02 repeat curl -I http://10.77.0.11.') + p('Observe failure. Work in order: IP reachability, listening socket, process/service state, configuration check, service log.') + p('Then restore:'))+code('sudo nginx -t\nsudo systemctl start nginx\ncurl -I http://127.0.0.1','UBU01 • Bash')+(actions('Repeat the remote request too.', 'Do not label a service incident “fixed” solely because its process started.'))),
step('5. Preserve evidence',code('mkdir -p ~/lab/week05\nsudo journalctl -u nginx --since today --no-pager > ~/lab/week05/nginx-journal.txt\nsudo tail -30 /var/log/nginx/access.log > ~/lab/week05/access-tail.txt\nsha256sum ~/lab/week05/*.txt')+p('Write what the access log can establish (requests recorded by nginx) and what it cannot establish (the real person behind an address or requests never reaching nginx).'))],
['Change and rollback plan','Before/after header output','Outage timeline with remote recovery proof'],['What can be listening when the application is still broken?','Why do we validate syntax before reload?'],
'nginx -t fails: restore the backup or correct the reported line before restarting. Empty journal is not always missing traffic: nginx access requests normally go to its access.log.',
'Create a tiny systemd service that runs python3 -m http.server 8080 as learner, then inspect its journal. Keep it private and remove the practice unit afterward.',
[('nginx beginner guide','https://nginx.org/en/docs/beginners_guide.html'),('journalctl manual','https://www.freedesktop.org/software/systemd/man/latest/journalctl.html')])

add(6,'SSH keys, firewalls, and a foundation exam','Systems',
'Authentication proves an identity; authorization decides what that identity may do. A firewall filters connections, not user intentions. SSH keys let the server verify possession of a private key without sending that key across the network.',
'UBU01 server + UBU02 client on private switch. Keep the UBU01 console open while changing SSH or firewall rules.',[
step('1. Create a client key',code('ssh-keygen -t ed25519 -f ~/.ssh/cyberlab_ed25519\nssh-copy-id -i ~/.ssh/cyberlab_ed25519.pub learner@10.77.0.11','UBU02 • Bash')+(actions('Set a passphrase when prompted.', 'Accept a host key only after comparing it with sudo ssh-keygen -lf /etc/ssh/ssh_host_ed25519_key.pub in UBU01’s console.') + p('The public key may be copied; the private file remains on UBU02. ssh-copy-id needs the learner password once.'))),
step('2. Prove key login before hardening',code('ssh -i ~/.ssh/cyberlab_ed25519 -o PasswordAuthentication=no learner@10.77.0.11','UBU02 • Bash')+(actions('Run hostname and whoami in the new session, then exit.', 'If this fails, fix key ownership and connectivity before proceeding.'))),
step('3. Configure the server safely',(p('On UBU01 create /etc/ssh/sshd_config.d/00-cyberlab.conf with the three lines below.') + p('A leading 00 makes this early in the include order; still verify effective settings because other configuration can affect them.'))+code('PasswordAuthentication no\nKbdInteractiveAuthentication no\nPermitRootLogin no','UBU01 • SSH configuration file')+code('sudo sshd -t\nsudo sshd -T | grep -E "passwordauthentication|kbdinteractiveauthentication|permitrootlogin"\nsudo systemctl reload ssh','UBU01 • Bash')+(actions('Use sudo nano to create the file as practiced in Week 3.', 'Do not reload if validation fails.', 'Open another key-authenticated session before closing the working console.') + p('Force a password-only attempt from UBU02 with ssh -o PubkeyAuthentication=no -o PreferredAuthentications=password learner@10.77.0.11; expect denial.'))),
step('4. Add a minimal firewall policy',code('sudo ufw default deny incoming\nsudo ufw default allow outgoing\nsudo ufw allow from 10.77.0.12 to any port 22 proto tcp\nsudo ufw allow from 10.77.0.0/24 to any port 80 proto tcp\nsudo ufw enable\nsudo ufw status numbered','UBU01 • Bash')+(actions('From UBU02 verify SSH and HTTP still work.', 'Then temporarily delete the numbered HTTP allow rule using sudo ufw delete NUMBER, where NUMBER is the current HTTP rule’s displayed index.') + p('Re-test HTTP with curl --max-time 5 -I http://10.77.0.11; expect failure.') + p('Re-add the HTTP rule and prove recovery.') + p('Rule numbers change after deletion; inspect them each time.'))),
step('5. Sit the foundation exam',(p('Without following earlier command blocks, explain the path of an HTTP request from UBU02 to nginx.') + p('Create a new read-only file for labreaders, prove another user is denied, stop/start a service, and locate the associated logs.') + p('Your mentor chooses one fault: wrong switch, stopped nginx, or wrong file permission. You get 45 minutes to diagnose, repair, and explain the evidence.')))],
['Key success and password denial evidence','Firewall allow/deny/recovery results','Foundation exam scored with the rubric'],['Why keep the VM console available during hardening?','What protection does a private-key passphrase provide?'],
'SSH lockout: use UBU01’s Hyper-V console. Check ufw status, sshd -t, effective sshd settings, and journalctl -u ssh. Restore only the changed file/rule. Do not globally disable every control as a first response.',
'For 9–12-hour weeks, rebuild UBU02 from the ISO and recover the notebook. Keep the private key out of public evidence.',
[('Ubuntu OpenSSH','https://documentation.ubuntu.com/server/how-to/security/openssh-server/'),('Ubuntu firewall','https://documentation.ubuntu.com/server/how-to/security/firewalls/')])
add(7,'Windows administration and event evidence','Systems',
'Windows uses security identifiers, access tokens, groups, services, and access-control lists. The GUI and PowerShell are two ways to inspect the same system. Event IDs are meaningful only with their provider, channel, time, and context.',
'WIN01 only: Windows Server 2025 Evaluation Desktop Experience, 4 GB RAM, 2 vCPU, 60 GB disk. Other VMs off.',[
step('1. Install the Windows practice machine',(p('At the Microsoft Evaluation Center download the Windows Server 2025 ISO to the host ISOs directory; registration may be required.') + p('Read evaluation terms and record the install/expiry dates.') + p('This is evaluation software, not open source. A host Windows license does not automatically license guests.') + actions('Create WIN01 in Hyper-V using Generation 2, 4096 MB fixed memory, 2 processors, 60 GB dynamic disk, Default Switch, and the ISO.', 'Use the Microsoft Windows Secure Boot template.'))),
step('2. Complete setup carefully',(actions('Boot the guest ISO and select language/keyboard → Install.', 'Choose Windows Server 2025 Standard Evaluation (Desktop Experience), accept terms, select Custom installation, and install onto the empty 60 GB guest disk.', 'Do not select an edition without Desktop Experience.', 'Set a unique Administrator password.', 'Use VM Connection → Action → Ctrl+Alt+Delete to sign in.', 'Install updates and activate the evaluation as directed by Microsoft while in update mode.', 'Download Sysmon from Microsoft’s official page inside WIN01, extract to C:\\Tools\\Sysmon for Week 13, and retain the original download.'))),
step('3. Set identity and private networking',code('Rename-Computer -NewName WIN01 -Restart','WIN01 • administrator Windows PowerShell')+(actions('After reboot, shut down and switch WIN01 to CyberLab-Private.', 'Start it, run ncpa.cpl, right-click the connected Ethernet adapter → Properties → Internet Protocol Version 4 → Properties.', 'Set IP 10.77.0.21, mask 255.255.255.0, and leave gateway/DNS empty for now.') + check('Confirm with ipconfig /all.') + p('Do not change the real laptop’s adapter.'))),
step('4. Create a standard identity',code('$labPassword = Read-Host "Choose a unique lab password" -AsSecureString\nNew-LocalUser -Name labuser -Password $labPassword\nAdd-LocalGroupMember -Group Users -Member labuser\nGet-LocalGroupMember -Group Administrators\nGet-LocalUser','WIN01 • administrator PowerShell')+(p('labuser must not appear in Administrators.') + actions('Sign out and sign in as .\\labuser once, then return to Administrator.', 'Record which operations requested elevation.', 'Keep Defender and Windows Firewall enabled.'))),
step('5. Test a Windows file boundary',(actions('Create C:\\LabData\\case.txt containing dummy information.', 'Right-click LabData → Properties → Security → Advanced.', 'Disable inheritance and choose to convert inherited permissions.') + p('Preserve SYSTEM and Administrators full control.') + actions('Remove ordinary Users/Authenticated Users entries if present; add WIN01\\labuser with Read & execute.', 'Apply to this folder/subfolders/files.') + p('As labuser, prove reading succeeds and editing case.txt fails.') + p('Return to Administrator and inspect:'))+code('icacls C:\\LabData\nGet-Service | Select-Object -First 10\nGet-NetTCPConnection -State Listen | Select-Object -First 15','WIN01 • administrator PowerShell')),
step('6. Find actual events',(actions('Open Event Viewer → Windows Logs → Security.', 'Look for a recent successful sign-in (4624) and inspect its details, including logon type.', 'Do not assume all 4624 events represent someone typing at a keyboard.'))+code("Get-WinEvent -FilterHashtable @{LogName='Security';Id=4624} -MaxEvents 5 | Format-List TimeCreated,Id,Message",'WIN01 • administrator PowerShell')+(actions('If the event is absent, inspect audit policy with auditpol /get /category:* rather than manufacturing evidence.', 'Export relevant events with Save Selected Events into the guest C:\\LabEvidence folder, which you create first.')))],
['Windows build and evaluation dates','Standard-user allowed/denied file tests','Annotated authentication event'],['What is elevation?','Why is a username alone insufficient to understand an event?'],
'No desktop: you selected Server Core; rebuild the practice VM with Desktop Experience. Network “unidentified” is expected on the private segment. Do not turn off the firewall to make the label change.',
'Compare Windows ACL inheritance to Linux directory permissions. Use Process Explorer only from its official Microsoft source.',
[('Windows Server evaluation','https://www.microsoft.com/en-us/evalcenter/evaluate-windows-server-2025'),('Windows event 4624','https://learn.microsoft.com/en-us/windows/security/threat-protection/auditing/event-4624'),('Sysmon download','https://learn.microsoft.com/en-us/sysinternals/downloads/sysmon')])

add(8,'Build a domain and understand DNS','Systems',
'Active Directory Domain Services (AD DS) centralizes identities and policy. DNS service records help clients locate domain controllers. Kerberos provides ticket-based authentication and depends on name resolution and reasonably synchronized clocks. AD DS and Microsoft Entra ID are different identity systems.',
'DC01 4 GB + WIN01 4 GB; all Linux and monitoring VMs off. Private switch. Domain: corp.example.test.',[
step('1. Create DC01',(p('Repeat the Week 7 installation in a fresh VM. Use a distinct local Administrator password.') + settings(('VM name','DC01'),('Memory / processors','4 GB / 2 vCPU'),('Virtual disk','60 GB')) + actions('Patch and activate on Default Switch before promoting the server.','Rename the guest DC01 and reboot.','Shut down, attach CyberLab-Private and boot into the guest console.','Configure the guest network adapter using the values below.') + settings(('IPv4','10.77.0.10'),('Subnet mask','255.255.255.0'),('Gateway','Leave blank'),('Preferred DNS','10.77.0.10')))),
step('2. Install a new forest',code('Install-WindowsFeature AD-Domain-Services -IncludeManagementTools\nInstall-ADDSForest -DomainName "corp.example.test" -DomainNetbiosName "CORP" -InstallDNS','DC01 • administrator PowerShell')+(actions('Choose and securely record the Directory Services Restore Mode password when asked.', 'Read the prerequisite checks.') + p('A parent DNS delegation warning is expected for this isolated new test forest; other errors require investigation.') + actions('Accept the restart.', 'Sign in as CORP\\Administrator.', 'Never use this domain name or lab password for a real organization.'))),
step('3. Validate the controller',code('Get-ADDomain\nGet-ADForest\nGet-Service NTDS,DNS,Netlogon\nResolve-DnsName -Type SRV _ldap._tcp.dc._msdcs.corp.example.test\ndcdiag /test:dns','DC01 • administrator PowerShell')+(check('Confirm the domain and a service record pointing at DC01.') + p('DNS diagnostics may flag lack of internet resolution; this private domain must resolve its own records.') + p('Record each failure and distinguish intentional lack of internet from broken internal DNS.'))),
step('4. Join WIN01',(p('On WIN01 set its Ethernet preferred DNS to 10.77.0.10; retain 10.77.0.21/24 and no gateway.') + p('The domain client must use domain DNS, not a public resolver.') + p('Check the SRV lookup before joining.'))+code('Resolve-DnsName -Type SRV _ldap._tcp.dc._msdcs.corp.example.test\nAdd-Computer -DomainName corp.example.test -Credential CORP\\Administrator -Restart','WIN01 • administrator PowerShell')+(actions('Enter the domain administrator credential at the prompt.', 'After restart, sign in with the domain Administrator for setup only.') + p('A member server is used here to avoid needing a separately licensed Windows client VM; it is not an exact desktop-client simulation.'))),
step('5. Understand what changed',code('whoami /all\n(Get-CimInstance Win32_ComputerSystem).Domain\nnltest /dsgetdc:corp.example.test\nklist','WIN01 • PowerShell')+(actions('Compare local and domain identities.', 'Draw client → DNS → domain controller, and mark where authentication and name lookup occur.', 'Keep both VMs’ clocks close to the host.', 'Do not add an internet adapter to the domain controller for convenience.')))],
['Domain DNS record and service status','WIN01 domain membership','Identity/DNS diagram'],['Why can a correct password fail if DNS is wrong?','What is the difference between CORP\\Administrator and WIN01\\Administrator?'],
'Join failure: check correct DNS, same Private switch, DC services, and time. An evaluation expiration is not an AD fault. Avoid rolling back only one machine in a domain pair; secure-channel state can diverge.',
'Inspect DNS Manager’s forward zone and _msdcs records. Explain SRV versus A records without changing them.',
[('Install AD DS','https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/deploy/install-active-directory-domain-services--level-100-')])

add(9,'Identity lifecycle and Group Policy','Systems',
'A group expresses an access role. An organizational unit (OU) scopes administration and policy. A Group Policy Object (GPO) is a configuration applied through scope and processing rules. Creating a policy is not proof that it reached the intended computer.',
'DC01 + WIN01, 8 GB total, private switch.',[
step('1. Create a small organization',(actions('On DC01 open Server Manager → Tools → Active Directory Users and Computers.', 'Under corp.example.test create OUs LabUsers and LabServers (right-click domain → New → Organizational Unit).', 'In LabUsers create user Abebe with sign-in name abebe and a unique temporary password; require password change at next logon.', 'Create a Global Security group CaseReaders and add Abebe as a member.', 'Move WIN01 from Computers into LabServers.', 'Keep DC01 in Domain Controllers.'))),
step('2. Exercise joiner/mover/leaver access',(p('On WIN01, as Administrator, add CORP\\CaseReaders read access to C:\\LabData using the Security dialog.') + p('Preserve administrator/SYSTEM entries.') + actions('Launch a prompt as Abebe with runas /user:CORP\\abebe powershell; change the password through interactive sign-in if required first.', 'Prove reading case.txt succeeds and writing fails.', 'On DC01 remove Abebe from CaseReaders.', 'Close all Abebe sessions and sign in anew before testing denial; old tokens can retain membership.', 'Re-add membership for the next exercise.'))),
step('3. Apply a visible computer policy',(actions('On DC01 open Group Policy Management.', 'Expand Forest → Domains → corp.example.test.', 'Right-click LabServers → Create a GPO in this domain, and Link it here.', 'Name it Lab-Logon-Notice.', 'Edit → Computer Configuration → Policies → Windows Settings → Security Settings → Local Policies → Security Options.', 'Set “Interactive logon: Message title for users attempting to log on” to CyberLab and the message text to Authorized training VM only.', 'Do not edit Default Domain Policy for this lab.'))),
step('4. Prove actual application',code('gpupdate /force\nNew-Item -ItemType Directory -Force C:\\LabEvidence\ngpresult /h C:\\LabEvidence\\week09-policy.html','WIN01 • administrator PowerShell')+(actions('Sign out and verify the notice at sign-in.', 'Open the report and find Lab-Logon-Notice under applied computer GPOs.') + p('This is stronger evidence than a screenshot of the policy editor alone.'))),
step('5. Disable and restore an account',(actions('On DC01 right-click Abebe → Disable Account.', 'Sign out of Abebe sessions and attempt a new domain sign-in while DC01 is running.') + check('Expect denial.') + p('Re-enable the account and prove a new sign-in succeeds.') + p('Record that disabling an account does not necessarily terminate already established sessions immediately.') + p('Unlink Lab-Logon-Notice if you want to remove the banner, then run gpupdate and verify.')))],
['Group membership access tests after new logons','Applied-policy report','Account-disable test and limits'],['How does group membership differ from OU placement?','Why are existing sessions relevant to offboarding?'],
'GPO not applied: verify WIN01 is in LabServers, link enabled, DNS/DC reachable, and computer policy settings used. Inspect gpresult before changing security filters.',
'Create a separate helpdesk identity and discuss narrowly delegated password resets. Document the proposed scope before implementing optional delegation.',
[('Group Policy console','https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/group-policy/group-policy-management-console'),('Policy scope','https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/group-policy/group-policy-scope')])

add(10,'HTTP, TLS, and application boundaries','Services',
'HTTP carries application messages over a connection. TLS encrypts transport and authenticates the server when certificate validation succeeds. Hashing detects changes; it does not hide information. A certificate being present is different from a client trusting the correct identity.',
'UBU01 + UBU02 only, private switch. Preserve the port-80 site from Week 5.',[
step('1. Read a request and response',code('curl -v http://10.77.0.11/\ncurl -I http://10.77.0.11/not-present','UBU02 • Bash')+(p('Identify method, path, Host header, response status, and content type.') + p('A 404 means the server answered but did not find the resource. A timeout means something different.') + p('Use only dummy headers and data in captures.'))),
step('2. Issue a lab certificate',code('sudo mkdir -p /etc/nginx/lab-tls\nsudo openssl req -x509 -newkey rsa:2048 -nodes -days 30 -keyout /etc/nginx/lab-tls/lab.key -out /etc/nginx/lab-tls/lab.crt -subj "/CN=10.77.0.11" -addext "subjectAltName=IP:10.77.0.11"\nsudo chmod 600 /etc/nginx/lab-tls/lab.key','UBU01 • Bash')+(p('This self-signed certificate is for the lab only. The SAN records the IP identity being tested. The unencrypted private key is protected by filesystem permissions; never export it as portfolio evidence.') + p('Record its 30-day expiry.'))),
step('3. Add HTTPS without removing HTTP',p('Use sudo nano /etc/nginx/sites-available/lab-tls and enter:')+code('server {\n    listen 443 ssl;\n    server_name 10.77.0.11;\n    ssl_certificate /etc/nginx/lab-tls/lab.crt;\n    ssl_certificate_key /etc/nginx/lab-tls/lab.key;\n    root /var/www/html;\n    location / { try_files $uri $uri/ =404; }\n}','UBU01 • nginx site file')+code('sudo ln -s /etc/nginx/sites-available/lab-tls /etc/nginx/sites-enabled/lab-tls\nsudo nginx -t\nsudo systemctl reload nginx\nsudo ufw allow from 10.77.0.0/24 to any port 443 proto tcp','UBU01 • Bash')+p('Create the symlink once. If syntax validation fails, correct it before reload.')),
step('4. Validate trust explicitly',code('curl -I https://10.77.0.11\nscp -i ~/.ssh/cyberlab_ed25519 learner@10.77.0.11:/etc/nginx/lab-tls/lab.crt ~/lab.crt\nopenssl x509 -in ~/lab.crt -noout -fingerprint -sha256 -dates\ncurl --cacert ~/lab.crt -I https://10.77.0.11','UBU02 • Bash')+(p('First request should fail certificate trust; final request should succeed.') + actions('Compare the fingerprint with openssl output on UBU01’s console before trusting the file.', 'Do not make -k or disabling certificate checks your permanent solution.'))),
step('5. Compare visibility',(actions('Repeat Week 3’s tcpdump capture with tcp port 80 or tcp port 443.', 'Generate one HTTP and one HTTPS request from UBU02.', 'Read with tcpdump -A -r FILE.') + p('HTTP headers are visible; TLS application content should not be readable. Both still expose traffic metadata.') + p('Inspect nginx access.log to see the server-side request record.')))],
['Certificate fingerprint, SAN, expiry, and trust test','HTTP/TLS packet comparison','Service diagram showing encryption termination'],['What does TLS not protect after the server decrypts a request?','Why is a hash not encryption?'],
'Certificate expired: issue a new lab certificate, reload nginx, verify fingerprint again, and replace the client trust file. Permission denied reading key: inspect file path and nginx startup privileges; do not make private keys world-readable.',
'Sketch a threat model for a small appointment app: assets, users, trust boundaries, three threats, and matching controls.',
[('nginx HTTPS configuration','https://nginx.org/en/docs/http/configuring_https_servers.html'),('OpenSSL req','https://docs.openssl.org/master/man1/openssl-req/')])

add(11,'Deploy your security monitoring stack','Detection',
'Wazuh’s agent observes an endpoint. Its manager parses events and applies rules. Its indexer stores searchable data. Its dashboard presents it. Installing the dashboard is not the same as proving collection, detection, or useful investigation.',
'WAZUH01 only during installation: 8 GB fixed RAM, 4 vCPU, 80 GB disk. Later add UBU01 2 GB. Keep all other guests off. Host needs roughly 5–6 GB free headroom; measure actual pressure.',[
step('1. Build WAZUH01',(actions('Repeat the Ubuntu installation procedure with VM/hostname WAZUH01/wazuh01, 8192 MB fixed RAM, 4 processors, 80 GB disk, and Ubuntu 24.04 Server.', 'Use Default Switch for installation and updates.', 'Install curl, nano, openssh-server, and ufw.', 'Do not install Docker or another search stack here.', 'If the host is already paging heavily with this VM alone, close apps or arrange a RAM upgrade/mentor-provided server before proceeding; do not quietly under-allocate Wazuh.'))),
step('2. Install a recorded release',(p('The official quickstart checked for this edition uses the 4.14 release family.') + actions('Open it before installation and check supported Ubuntu versions and any changed instructions.', 'Do not mix a newer agent with an older manager.', 'In the guest run:'))+code('curl --fail --show-error --location -o wazuh-install.sh https://packages.wazuh.com/4.14/wazuh-install.sh\nless wazuh-install.sh\nsudo bash ./wazuh-install.sh -a','WAZUH01 • Bash, update mode')+(p('q exits less. The installer requires internet and may take time; review failures rather than repeatedly rerunning it. Store the generated credentials and installation archive privately.') + actions('Do not paste installation output containing passwords into the notebook.', 'Record installed package versions with dpkg-query -W wazuh-manager wazuh-indexer wazuh-dashboard.'))),
step('3. Verify each component',code('sudo systemctl is-active wazuh-manager wazuh-indexer wazuh-dashboard filebeat\nfree -h\ndf -h /\nsudo ss -lntp','WAZUH01 • Bash')+(check('Expect active services and sufficient free disk.') + actions('If the dashboard is not ready, inspect that service’s journal.', 'Keep the indexer’s 9200 and manager API’s 55000 ports unexposed to general clients.'))),
step('4. Move to the private segment',(actions('Use Week 3’s network procedure to give WAZUH01 10.77.0.30/24, with no gateway/DNS, on CyberLab-Private.', 'Enable ufw with default deny incoming and allow outgoing.', 'Allow TCP 22 from 10.77.0.11 only, TCP 1514 and 1515 from 10.77.0.0/24, and TCP 443 from 10.77.0.0/24.', 'Allow rules first, then enable ufw.', 'Keep its console available.', 'Start only UBU01 alongside it.'))),
step('5. Reach the dashboard through a narrow temporary path',(p('The real host cannot directly reach a Private switch.') + actions('For setup only, shut down UBU01 and add a second Network Adapter in Hyper-V Settings → Add Hardware → Network Adapter, connected to Default Switch.', 'Start it; identify the new interface with ip -br link and its MAC against Hyper-V.', 'Add that interface to UBU01’s netplan with dhcp4: true while preserving eth0’s private static address.', 'Apply.') + p('Temporarily allow SSH from the Default Switch host IP to the new interface using ufw.') + actions('Find that host IP in host ipconfig under vEthernet (Default Switch).', 'Do not enable IP forwarding or bridging on UBU01.'))+code('ssh -i "$env:USERPROFILE\\.ssh\\cyberlab_host" -N -L 8443:10.77.0.30:443 learner@REPLACE_WITH_UBU01_DEFAULT_IP','HOST • PowerShell; replace the IP token')+(p('Because UBU01 is key-only, first create a separate host SSH key using the explicit cyberlab_host key-generation command in the lab handbook if you lack one.') + actions('Copy only its .pub line into UBU01’s ~/.ssh/authorized_keys via the VM console (nano); preserve the existing UBU02 public key.', 'Set ~/.ssh to 700 and authorized_keys to 600.') + check('Verify UBU01’s host fingerprint before connecting.') + p('Open https://localhost:8443 in the host browser, accept only the known lab certificate after checking its fingerprint in the WAZUH01 console, then sign in. localhost will not match the lab certificate name; this is a scoped tunnel exception.') + p('A simpler alternative on a 32 GB host is a private Windows browser guest.'))),
step('6. Close the temporary path',(actions('After dashboard work, close the SSH tunnel with Ctrl+C.', 'Shut UBU01 down and remove only its added Default Switch adapter.', 'Remove the corresponding netplan entry and temporary host-SSH ufw rule in its console.') + check('Verify the private-only state.') + p('This temporary management procedure is reused for dashboard sessions; no vulnerable container or active scan may run while it is connected.') + p('Keep Wazuh package upgrades coordinated; review official release guidance before updating the manager and agents.')))],
['Component/service and version inventory','Dashboard screenshot without secrets','Memory measurement and management-path diagram'],['Where does parsing occur and where is data searched?','Why is dashboard login not a detection test?'],
'Host paging: stop other VMs; if WAZUH01 + UBU01 is still impractical, use a mentor server or RAM upgrade. Tunnel failure: test UBU01 → 10.77.0.30:443, then host → UBU01 SSH. No listener on 8443: the tunnel is not running.',
'Draw failure symptoms for agent, manager, indexer, and dashboard separately. Explain which service you would inspect first for each symptom.',
[('Wazuh quickstart and sizing','https://documentation.wazuh.com/current/quickstart.html'),('Wazuh architecture','https://documentation.wazuh.com/current/getting-started/architecture.html')])

add(12,'Collect Linux events and prove file monitoring','Detection',
'Collection brings events to the manager; detection turns selected events into alerts. File integrity monitoring (FIM) notices changes relative to a baseline. An alert is a lead for investigation, not automatic proof of malicious activity.',
'WAZUH01 8 GB + UBU01 2 GB. Private switch for tests. Use the temporary management path only to inspect results afterward.',[
step('1. Install a matching Linux agent',(actions('In UBU01 update mode, download the Linux amd64 DEB matching your recorded Wazuh manager release from the official packages list.', 'For the checked release the filename is wazuh-agent_4.14.7-1_amd64.deb.', 'If the manager differs, select the matching package instead.', 'Compare the published SHA512 hash using sha512sum.') + p('Bring UBU01 back to private mode before starting enrollment.'))+code('sudo env WAZUH_MANAGER="10.77.0.30" WAZUH_AGENT_NAME="UBU01" dpkg -i ./wazuh-agent_4.14.7-1_amd64.deb\nsudo systemctl daemon-reload\nsudo systemctl enable --now wazuh-agent\nsudo tail -40 /var/ossec/logs/ossec.log','UBU01 • Bash; run from the download directory')+(p('If installation reports missing dependencies, resolve them in update mode using apt, then return private.') + check('Expect a successful manager connection.') + p('The enrollment port is TCP 1515 and event traffic uses TCP 1514 in this course.'))),
step('2. Verify at both ends',code('sudo /var/ossec/bin/agent_control -l','WAZUH01 • Bash')+(actions('Find UBU01 as active.', 'In the dashboard select Agents management → Summary and open UBU01.', 'Record last keepalive and version.', 'If dashboard labels change, look for the agent inventory rather than assuming collection failed.'))),
step('3. Configure a tiny FIM scope',(actions('On UBU01 back up /var/ossec/etc/ossec.conf.', 'Open with sudo nano.') + p('Inside the existing syscheck block add the directory entry below; do not create a second syscheck block or overwrite the whole file.'))+code('<directories realtime="yes" check_all="yes">/srv/labshare</directories>','UBU01 • inside existing <syscheck>')+code('sudo systemctl restart wazuh-agent\nsudo tail -30 /var/ossec/logs/ossec.log','UBU01 • Bash')+(actions('Wait for the initial scan to finish before changing a file.', 'If service startup reports an XML error, restore the backup and correct the tag placement.'))),
step('4. Generate and correlate one change',code('date -u\nprintf "week12 approved change\\n" | sudo tee -a /srv/labshare/case.txt\nsudo sha256sum /srv/labshare/case.txt','UBU01 • Bash')+(actions('Wait up to a few minutes.', 'In Wazuh’s file integrity view, filter agent UBU01 and the exact file path; expand the time range if needed.', 'Identify action, timestamp, and changed attributes.', 'On the manager inspect sudo tail -50 /var/ossec/logs/alerts/alerts.json.') + p('An unchanged rewrite may not produce the same alert as a content change.'))),
step('5. Prove the collection boundary',(p('Create ~/unmonitored-lab.txt outside the configured directory and change its contents.') + p('Your custom directory monitoring should not claim coverage there.') + actions('Check other default FIM paths before concluding it is unmonitored.', 'Then stop the UBU01 agent for two minutes, change the monitored file once, restart it, and record whether a later scan reports the difference.', 'Do not assume realtime collection reconstructs every missed intermediate edit.'))),
step('6. Write a detection test record',(actions('Document event generation time, source file, agent status, manager alert, dashboard evidence, latency, and collection gaps.', 'Remove test-only data if necessary after saving evidence.', 'Keep the FIM scope small to avoid flooding or exposing real documents.')))],
['Active agent at endpoint and manager','FIM change with source-to-dashboard trace','Negative test and stopped-agent coverage limitation'],['What is the baseline?','Why can a file alert be expected administrative activity?'],
'No alert: check agent connection, exact monitored path, baseline completion, changed content, manager alerts.json, and dashboard time filter in that order. Do not reinstall the stack as the first diagnostic step.',
'Configure one additional dummy directory and compare content, owner, and permission change alerts.',
[('Agent packages','https://documentation.wazuh.com/current/installation-guide/packages-list.html'),('Linux deployment','https://documentation.wazuh.com/current/installation-guide/wazuh-agent/wazuh-agent-package-linux.html'),('FIM configuration','https://documentation.wazuh.com/current/user-manual/capabilities/file-integrity/how-to-configure-fim.html')])
add(13,'Capture Windows process telemetry','Detection',
'Sysmon adds detailed system events. Process creation records can connect an image, command line, parent, user, and timestamp. This week separates event capture from analysis to fit 16 GB: exported JSON is a replay dataset, not a live Windows agent connection.',
'Stage A: WIN01 4 GB, optionally DC01 4 GB for domain logon. Stage B: WAZUH01 8 GB + UBU01 2 GB. Never all together.',[
step('1. Install Sysmon on WIN01',(actions('Use the official Sysmon archive downloaded in Week 7.', 'In administrator PowerShell change to C:\\Tools\\Sysmon.', 'Inspect the digital signature with Get-AuthenticodeSignature .\\Sysmon64.exe and require a valid Microsoft signature.', 'Then install the basic configuration:'))+code('.\\Sysmon64.exe -accepteula -i\nGet-Service Sysmon64','WIN01 • administrator PowerShell')+(p('Read the license before accepting it.') + p('Default Sysmon captures process creation; do not assume all optional event types such as network connections are enabled.') + p('Keep the default configuration for this exercise.'))),
step('2. Produce a known event',code('New-Item -ItemType Directory -Force C:\\LabEvidence\ncmd.exe /c "echo CYBERLAB-W13"\nGet-WinEvent -FilterHashtable @{LogName="Microsoft-Windows-Sysmon/Operational";Id=1} -MaxEvents 20 | Format-List TimeCreated,Id,Message','WIN01 • administrator PowerShell')+(actions('Open Event Viewer → Applications and Services Logs → Microsoft → Windows → Sysmon → Operational.', 'Find cmd.exe with CYBERLAB-W13, its parent process and user.') + p('This is a benign command, not malware.'))),
step('3. Export raw and normalized evidence',code('wevtutil epl Microsoft-Windows-Sysmon/Operational C:\\LabEvidence\\sysmon.evtx\n$rows = Get-WinEvent -FilterHashtable @{LogName="Microsoft-Windows-Sysmon/Operational";Id=1} -MaxEvents 30 | ForEach-Object {\n  [xml]$eventXml = $_.ToXml()\n  $fields = @{}\n  foreach ($item in $eventXml.Event.EventData.Data) { $fields[$item.Name] = $item.InnerText }\n  [ordered]@{lab_source="windows_replay";event_id=1;event_time=$_.TimeCreated.ToUniversalTime().ToString("o");image=$fields["Image"];command_line=$fields["CommandLine"];parent_image=$fields["ParentImage"];user=$fields["User"]} | ConvertTo-Json -Compress\n}\n[IO.File]::WriteAllLines("C:\\LabEvidence\\windows-events.json", [string[]]$rows, [Text.UTF8Encoding]::new($false))\nGet-FileHash C:\\LabEvidence\\sysmon.evtx -Algorithm SHA256','WIN01 • administrator PowerShell')+(p('Keep raw EVTX separately from derived JSON.') + p('The JSON schema is this course’s schema and does not match Wazuh’s native Windows event-channel schema.') + p('Inspect and redact account identifiers before public sharing; never collect real passwords in command lines.'))),
step('4. Retrieve the JSON without a network bridge',code('$guestCred = Get-Credential -Message "WIN01 local Administrator credential"\n$eventText = Invoke-Command -VMName WIN01 -Credential $guestCred -ScriptBlock { Get-Content C:\\LabEvidence\\windows-events.json -Raw }\n[IO.File]::WriteAllText("C:\\CyberLab\\Private\\windows-events.json", [string]$eventText, [Text.UTF8Encoding]::new($false))','HOST • administrator PowerShell')+(p('PowerShell Direct uses Hyper-V guest integration.') + actions('Enter WIN01\\Administrator and the local password, so DC01 is not required for this step.', 'Check Get-Content on the host produces one JSON object per line.', 'Keep the original EVTX in the VM or export it using a binary-safe transfer, not this text method.', 'Shut WIN01/DC01 down.'))),
step('5. Stage the replay for next week',(actions('Start UBU01 and WAZUH01.', 'Use Week 11’s temporary management connection to UBU01, and from the host use scp -i "$env:USERPROFILE\\.ssh\\cyberlab_host" C:\\CyberLab\\Private\\windows-events.json learner@UBU01_DEFAULT_IP:~/windows-events.json, replacing the address.', 'From UBU01 copy to WAZUH01 using scp ~/windows-events.json learner@10.77.0.30:~/windows-events.json; verify its SSH fingerprint in the manager console.') + p('WAZUH01 uses its own learner password unless you configure a key.') + actions('Remove UBU01’s temporary adapter afterward.', 'Keep the replay file for Week 14.'))),
step('6. Compare native collection with replay',(p('Write what this experiment proves: Sysmon produced a process event and you preserved selected fields.') + p('It does not prove a live Windows agent, continuous coverage, delivery latency, or native Wazuh Windows detections.') + p('Optional with 32 GB or a mentor-hosted manager: deploy a matching Windows Wazuh agent from Agents management → Deploy new agent, set manager 10.77.0.30 on the private network, add a localfile eventchannel block for Microsoft-Windows-Sysmon/Operational, restart WazuhSvc, and verify the same marker in native events.')))],
['Raw Sysmon event and parent/child explanation','Hashed EVTX plus normalized JSON','Explicit live-versus-replay limitations'],['Why preserve raw evidence before transforming it?','Does a process event tell you whether the action was authorized?'],
'PowerShell Direct failure: confirm WIN01 is running, use host administrator PowerShell and a valid local guest credential. Sysmon event absent: check channel/service, run a new cmd marker, and adjust time range. Do not claim network event coverage from defaults.',
'With additional RAM, implement the optional native Windows agent and compare its schema to the replay. Keep this outside the 16 GB core requirement.',
[('Sysmon event reference','https://learn.microsoft.com/en-us/sysinternals/downloads/sysmon'),('PowerShell Direct','https://learn.microsoft.com/en-us/virtualization/hyper-v-on-windows/user-guide/powershell-direct'),('Windows event-channel collection','https://documentation.wazuh.com/current/user-manual/capabilities/log-data-collection/configuration.html')])

add(14,'Write and test your first detection rules','Detection',
'A detection is a testable claim about evidence. It needs a data source, match logic, known positive and negative cases, and a response. Severity is a prioritization signal. A synthetic marker demonstrates plumbing; it is not a production threat detector.',
'WAZUH01 + UBU01, 10 GB total. Use WAZUH01 console for edits, dashboard tunnel for later review.',[
step('1. Configure a replay log source',p('On WAZUH01 create the destination before enabling collection:')+code('sudo mkdir -p /var/log/cyberlab\nsudo touch /var/log/cyberlab/replay.json\nsudo chmod 640 /var/log/cyberlab/replay.json\nsudo cp /var/ossec/etc/ossec.conf /var/ossec/etc/ossec.conf.w14-backup\nsudo nano /var/ossec/etc/ossec.conf','WAZUH01 • Bash')+p('Inside the existing ossec_config element add:')+code('<localfile>\n  <log_format>json</log_format>\n  <location>/var/log/cyberlab/replay.json</location>\n</localfile>','WAZUH01 • ossec.conf addition')),
step('2. Define two small rules',(p('Create /var/ossec/etc/rules/cyberlab_rules.xml with sudo nano.') + p('IDs 100100 and 100101 must be unique in your custom directory; check with sudo grep -R 10010 /var/ossec/etc/rules before saving.'))+code('<group name="cyberlab,">\n  <rule id="100100" level="5">\n    <decoded_as>json</decoded_as>\n    <field name="lab_source">^cyberlab$</field>\n    <field name="action">^test_alert$</field>\n    <description>CyberLab synthetic pipeline test</description>\n  </rule>\n  <rule id="100101" level="5">\n    <decoded_as>json</decoded_as>\n    <field name="lab_source">^windows_replay$</field>\n    <field name="command_line" type="pcre2">CYBERLAB-W13</field>\n    <description>CyberLab replayed Windows marker</description>\n  </rule>\n</group>','WAZUH01 • cyberlab_rules.xml')),
step('3. Test before restarting',code('sudo /var/ossec/bin/wazuh-logtest','WAZUH01 • Bash')+(p('Paste each of these lines separately into logtest.') + p('The first should match 100100; the second should not match your custom marker rule.') + p('Inspect decoder fields and rule ID, not just any generic match.'))+code('{"lab_source":"cyberlab","action":"test_alert","case":"W14-A"}\n{"lab_source":"cyberlab","action":"normal","case":"W14-B"}','Input to wazuh-logtest')+(p('Paste the real CYBERLAB-W13 line from windows-events.json and verify 100101.') + p('Exit with Ctrl+C.') + actions('Save a short test table.', 'If a rule fails parsing, correct it before service restart.'))),
step('4. Exercise the live collection path',code('sudo systemctl restart wazuh-manager\nsudo systemctl is-active wazuh-manager\nprintf \'%s\\n\' \'{"lab_source":"cyberlab","action":"test_alert","case":"W14-A"}\' | sudo tee -a /var/log/cyberlab/replay.json\ncat ~/windows-events.json | sudo tee -a /var/log/cyberlab/replay.json > /dev/null\nsudo tail -40 /var/ossec/logs/alerts/alerts.json','WAZUH01 • Bash')+(p('Append after the collector starts.') + p('In the dashboard filter rule.id:100100 or rule.id:100101 and a recent time range.') + p('Replay ingestion time is now, while event_time in the Windows data is the original event time. This distinction belongs in the report.'))),
step('5. Tune and describe limitations',(p('Append the normal test event and verify it does not trigger 100100. Try a similar marker with different case; document whether it matches.') + actions('Write a rule card: purpose, source/schema, exact match, test data, expected false positives, possible evasions, response, and owner.', 'Never automatically block a user solely because this training marker appeared.')))],
['Positive and negative rule tests','Manager alert and dashboard trace','Rule card with replay-time caveat'],['Why can logtest success still fail to produce a dashboard event?','What distinguishes this marker test from a useful threat detection?'],
'logtest works but no live alert: confirm watched path, append after startup, collector log, manager state, and dashboard filters. Check XML placement and unique IDs. Do not edit bundled rules under /var/ossec/ruleset.',
'Add a second benign marker rule with a different ID, then ask your mentor to supply a nonmatching sample that exposes an assumption.',
[('Custom Wazuh rules','https://documentation.wazuh.com/current/user-manual/ruleset/rules/custom.html'),('JSON decoder','https://documentation.wazuh.com/current/user-manual/ruleset/decoders/json-decoder.html'),('Rule syntax','https://documentation.wazuh.com/current/user-manual/ruleset/ruleset-xml-syntax/rules.html')])

add(15,'Build a network sensor with Suricata','Detection',
'A network intrusion detection system interprets traffic visible at its capture interface. Visibility is a topology property. Putting a sensor VM on a switch does not guarantee it sees every conversation. This lab captures traffic addressed to UBU01, then demonstrates a controlled ICMP detection.',
'UBU01 sensor/web server + UBU02 generator, 4 GB total. Wazuh off during packet generation.',[
step('1. Install the sensor',(p('Put UBU01 in update mode with nginx stopped.') + actions('Use OISF’s stable repository, not development builds.', 'Record the installed version.'))+code('sudo apt install software-properties-common\nsudo add-apt-repository ppa:oisf/suricata-stable\nsudo apt update\nsudo apt install suricata jq\nsuricata --build-info\nsudo systemctl stop suricata','UBU01 • Bash, update mode')+(p('Return UBU01 and UBU02 to CyberLab-Private.') + check('Confirm the capture interface using ip -br address.') + p('Examples below use eth0.'))),
step('2. Add one transparent rule',code('sudo mkdir -p /etc/suricata/rules\nsudo nano /etc/suricata/rules/cyberlab.rules','UBU01 • Bash')+code('alert icmp any any -> 10.77.0.11 any (msg:"CYBERLAB ICMP request"; itype:8; sid:1000001; rev:1;)','UBU01 • cyberlab.rules')+p('The rule alerts on an echo request to this VM. It is intentionally a demonstration, not evidence of attack. sid identifies the signature; rev tracks your revisions.')),
step('3. Validate configuration',(actions('Back up /etc/suricata/suricata.yaml.', 'Open it and set HOME_NET to "[10.77.0.0/24]".', 'In the existing eve-log output verify enabled: yes and that types includes alert.', 'Keep the other defaults.', 'Run the test using only your training rule:'))+code('sudo suricata -T -c /etc/suricata/suricata.yaml -S /etc/suricata/rules/cyberlab.rules','UBU01 • Bash')+p('Uppercase -S loads only the given rule file for this controlled test. Require a successful configuration test before capture.')),
step('4. Capture a predictable event',code('sudo suricata -c /etc/suricata/suricata.yaml -S /etc/suricata/rules/cyberlab.rules -i eth0','UBU01 • Bash; foreground, replace interface if needed')+code('ping -c 3 10.77.0.11','UBU02 • Bash')+p('Return to UBU01 and press Ctrl+C after the ping completes. Inspect alerts:')+code('sudo jq -c \'select(.event_type=="alert") | {timestamp,src_ip,dest_ip,signature:.alert.signature,sid:.alert.signature_id}\' /var/log/suricata/eve.json','UBU01 • Bash')+(check('Expect your signature and source 10.77.0.12.') + p('Repeated runs append data; filter by current timestamp to avoid counting old results.'))),
step('5. Run a negative test',(actions('Start the same foreground sensor again.', 'From UBU02 request HTTP from UBU01 instead of pinging: curl -I http://10.77.0.11.', 'If nginx is stopped, start it first.', 'Stop capture and verify this HTTP request did not create a new ICMP signature alert.') + p('Logs may still contain non-alert flow/HTTP records.'))),
step('6. Save the configuration and scope',(p('Preserve your rule, a sanitized alert, the tested version, and a diagram showing the capture point on UBU01.') + actions('Explain that this setup observes its own traffic, not UBU02-to-another-VM traffic.', 'Do not invent whole-network coverage.', 'Keep the service stopped; next week uses the same explicit foreground capture command.')))],
['Successful Suricata configuration test','ICMP positive and HTTP negative test','Capture-point diagram'],['What could a healthy sensor still fail to see?','Why is ping not automatically malicious?'],
'No packets: wrong interface/switch or generator target. Packets but no alerts: confirm rule loaded, destination, ICMP type, output path, and current timestamps. “Device busy” or duplicate records: stop the packaged service before foreground capture.',
'Use a saved PCAP with suricata -r and a new output directory. Compare replay time to packet event time. Port mirroring is an optional later topology exercise.',
[('Suricata stable Ubuntu installation','https://docs.suricata.io/en/suricata-8.0.5/install/ubuntu.html'),('Suricata rules','https://docs.suricata.io/en/suricata-8.0.5/rules/intro.html'),('Suricata EVE output','https://docs.suricata.io/en/suricata-8.0.5/output/eve/eve-json-output.html')])

add(16,'Integrate network alerts and investigate a case','Detection',
'Integration requires a chain of evidence: packet → sensor JSON → agent collection → manager rule → searchable alert → analyst decision. Each boundary can fail independently. A case report distinguishes observed facts, hypotheses, and unknowns.',
'WAZUH01 8 GB + UBU01 2 GB. Generate test traffic from WAZUH01 itself; UBU02 and Windows off.',[
step('1. Collect Suricata JSON',(p('On UBU01 back up ossec.conf.') + p('Inside its existing ossec_config add the following localfile block, preserving the FIM settings. Restart the agent and inspect its log.'))+code('<localfile>\n  <log_format>json</log_format>\n  <location>/var/log/suricata/eve.json</location>\n</localfile>','UBU01 • Wazuh agent ossec.conf')+code('sudo systemctl restart wazuh-agent\nsudo tail -30 /var/ossec/logs/ossec.log','UBU01 • Bash')),
step('2. Produce fresh sensor evidence',(actions('Use Week 15’s foreground Suricata command on UBU01.', 'On WAZUH01 run ping -c 3 10.77.0.11.', 'Stop the foreground sensor after the test.') + check('Verify current EVE alerts locally before looking in the dashboard.'))),
step('3. Verify the manager layer',code('sudo tail -100 /var/ossec/logs/alerts/alerts.json | jq -c \'select(.rule.groups[]? == "suricata")\'','WAZUH01 • Bash')+(p('A short tail can miss earlier alerts.') + actions('If necessary search the file for CYBERLAB ICMP request using sudo grep.', 'In the dashboard use rule.groups:suricata and agent.name:UBU01.', 'Expand the event; confirm the signature ID, source 10.77.0.30, destination 10.77.0.11, and timestamp.'))),
step('4. Build a case from evidence',(actions('Create case LAB-016.', 'Write a UTC timeline: approved test start, packet generation, EVE event, manager alert, analyst review.') + p('Assess whether the activity is expected.') + actions('Attach only sanitized excerpts with hashes for original files kept privately.', 'Close as authorized training activity with the evidence supporting that decision.'))),
step('5. Exercise a collection failure',(p('Back up the working agent config.') + p('Temporarily change only the Suricata localfile location to /var/log/suricata/not-present.json. Restart the agent, generate one ping test, and show that local Suricata evidence exists while central visibility does not.') + actions('Restore the correct path, restart the agent, and generate a new test to prove recovery.', 'Do not assume every event during the gap will be backfilled.')))],
['Source-to-alert trace','A completed LAB-016 case','Collection-gap diagnosis and fresh recovery test'],['What evidence justifies closing the case?','At which layer did the deliberate failure occur?'],
'Native integration schema differs across releases: inspect the actual EVE object and manager decoder output with wazuh-logtest. Do not force a hardcoded dashboard query to fit absent fields; document actual field names.',
'Compare one FIM event and one network event in the same timeline. Explain why correlation in time does not alone prove causation.',
[('Wazuh network IDS integration','https://documentation.wazuh.com/current/proof-of-concept-guide/integrate-network-ids-suricata.html')])

add(17,'Assess exposure and prioritize remediation','Assurance',
'An open port is exposure, not automatically a vulnerability. A package version alone may mislead when distributions backport fixes. Vulnerability management combines asset importance, reachability, evidence, remediation, and retesting. A hardening score is a guide, not a complete risk measure.',
'UBU01 + UBU02, 4 GB total. No scanning outside 10.77.0.11. Wazuh off.',[
step('1. Install a local configuration auditor',(actions('In UBU01 update mode install the open-source Lynis package and record its version.', 'Return to private mode before scanning.', 'Stop Suricata’s foreground process if still running.'))+code('sudo apt install lynis\nlynis show version','UBU01 • Bash, update mode')),
step('2. Inventory before scanning',code('hostnamectl\nsudo ss -lntup\ndpkg-query -W nginx openssh-server openssl\nsudo ufw status verbose','UBU01 • Bash')+p('Create an asset row: owner learner, purpose lab web service, data dummy, criticality low, private-only exposure, patch date, and installed versions.')),
step('3. Perform a bounded service scan',code('mkdir -p ~/lab/week17\nnmap -sT -sV -Pn -p 22,80,443 10.77.0.11 -oA ~/lab/week17/ubu01-services','UBU02 • Bash')+(p('The scan is limited to three known ports on the owned guest.') + p('Compare results with ss and firewall rules.') + p('Filtered, closed, and open mean different things. The output is evidence of observed service behavior, not a proven CVE.'))),
step('4. Audit configuration',code('sudo lynis audit system\nsudo cp /var/log/lynis-report.dat /tmp/lynis-before.dat\nsudo chmod 600 /tmp/lynis-before.dat','UBU01 • Bash')+(actions('Read warnings/suggestions and choose two relevant findings, not the entire list.', 'For each, state impact, evidence, whether it applies to this lab, a change, and a rollback.', 'Never apply a hardening script blindly.'))),
step('5. Remediate an unnecessary service',(p('Treat nginx as unnecessary for this one exercise.') + actions('Save baseline output, then stop and disable it.', 'Do not uninstall it; later weeks reuse it.'))+code('sudo systemctl disable --now nginx\nsudo ss -lntp','UBU01 • Bash')+(p('Repeat the three-port scan from UBU02.') + p('Ports 80/443 should no longer be open.') + p('Restore nginx with sudo systemctl enable --now nginx and verify both services again.') + p('This reversible demonstration proves exposure reduction without asserting that nginx itself was vulnerable.'))),
step('6. Write the remediation report',(actions('Document three items: the unnecessary-service exercise, one validated Lynis finding, and one finding you defer with a reason.', 'If you research a CVE, use the distribution security advisory for the installed package release and record fix status.') + p('Separate confirmed vulnerability, configuration weakness, and unverified scanner suggestion.')))],
['Service inventory matched to scan','Before/after/recovery exposure test','Three-item prioritized remediation register'],['Why might a banner version produce a false positive?','Why is remediation incomplete before retesting?'],
'Scan and ss disagree: check bound address, firewall, correct VM/IP, and whether you scanned before or after the change. A failed internet update in private mode is expected; use the defined update procedure.',
'Read an Ubuntu security notice for a package you installed, and explain backported fixes. Optional Wazuh vulnerability assessment needs current feeds and a separately documented online session.',
[('Nmap reference','https://nmap.org/book/man.html'),('Lynis documentation','https://cisofy.com/documentation/lynis/'),('Ubuntu security notices','https://ubuntu.com/security/notices')])

add(18,'Contain, preserve, and recover an incident','Response',
'Incident response protects operations while preserving enough evidence to make decisions. Containment limits impact; eradication removes the cause; recovery restores trusted service. A lab simulation can teach this workflow without executing malware or stealing credentials.',
'Stage A UBU01 + UBU02. Stage B WAZUH01 + UBU01 if reviewing FIM. Never exceed the 10 GB guest budget.',[
step('1. Prepare the case and baseline',(p('Create case LAB-018 and a timeline.') + check('Verify /srv/labshare/case.txt contains only dummy data.') + actions('Save a copy and hash in ~/lab/week18 before any simulation.', 'Note current nginx and firewall state.'))+code('mkdir -p ~/lab/week18\nsudo cp -a /srv/labshare/case.txt ~/lab/week18/case.before.txt\nsudo sha256sum /srv/labshare/case.txt > ~/lab/week18/before.sha256\nsudo ufw status numbered','UBU01 • Bash')),
step('2. Simulate an unauthorized-looking change',code('date -u\nprintf "SIMULATED UNAPPROVED CHANGE W18\\n" | sudo tee -a /srv/labshare/case.txt\nsudo sh -c \'cd /srv/labshare && python3 -m http.server 8088 --bind 10.77.0.11\'','UBU01 • Bash; foreground server')+(p('This exposes only dummy files on a lab port.') + actions('In another UBU01 console or SSH session, add a temporary ufw allow rule from 10.77.0.12 to TCP 8088.', 'From UBU02 request http://10.77.0.11:8088/case.txt and record the status.') + p('The simulation is staged; do not report it as real compromise.'))),
step('3. Preserve before stopping the process',(actions('Use a second UBU01 session.', 'If UBU02 is used for SSH, use the key from Week 6.', 'Capture process, socket, file hash, and UTC time:'))+code('mkdir -p ~/lab/week18\ndate -u > ~/lab/week18/collection-time.txt\nps -ef > ~/lab/week18/processes.txt\nsudo ss -lntup > ~/lab/week18/sockets.txt\nsudo sha256sum /srv/labshare/case.txt > ~/lab/week18/file-hash.txt\nsudo journalctl --since "20 minutes ago" --no-pager > ~/lab/week18/journal.txt','UBU01 • Bash')+(p('Record collector, source, collection method, timezone, and limits.') + p('This is basic triage, not a forensic disk acquisition.'))),
step('4. Contain and verify',(actions('Delete only the temporary ufw 8088 allow rule by its current displayed number.', 'From UBU02 repeat the HTTP request with --max-time 5 and prove it is blocked.') + p('Preserve console access.') + p('Return to the foreground Python process and press Ctrl+C.') + check('Verify 8088 is no longer listening.') + p('Do not kill unrelated processes by broad name matching.'))),
step('5. Restore and investigate the gap',(p('Restore case.txt from the pre-simulation copy and verify its original hash and permissions.') + check('Confirm normal nginx HTTP still works from UBU02.') + actions('If reviewing FIM, shut down UBU02 and start WAZUH01; inspect what the agent retained or detected later.', 'Explain why an offline manager means you cannot assume a complete realtime timeline.'))+code('sudo cp -a ~/lab/week18/case.before.txt /srv/labshare/case.txt\nsudo sha256sum -c ~/lab/week18/before.sha256\nsudo ls -l /srv/labshare/case.txt','UBU01 • Bash')),
step('6. Deliver an incident report',(p('Include scope, impact (dummy data only), observed facts, hypothesis, containment, evidence preserved, recovery tests, root cause of the simulation, and two improvements.') + actions('Identify what a real organization would need beyond this lab: authority, communications, legal/HR coordination where appropriate, and forensic expertise.', 'Do not invent exfiltration or attacker attribution from a request log.')))],
['Evidence manifest and timeline','Contained 8088 with normal service preserved','Recovery hash and incident report'],['Why capture process details before stopping it?','What distinguishes observed access from proven data exfiltration?'],
'No second console available: connect by SSH from UBU02 before starting the foreground server. Permission errors writing evidence: keep output in your home directory and apply sudo to the data source, not a broad interactive root session.',
'Ask the mentor to change one detail—different port or a stopped service—and repeat diagnosis without seeing the simulation steps.',
[('NIST incident response publication','https://csrc.nist.gov/pubs/sp/800/61/r3/final')])
add(19,'Back up data and prove a restore','Response',
'Recovery point objective (RPO) describes tolerable data loss in time. Recovery time objective (RTO) describes tolerable restoration time. A backup that cannot be restored is an unproven control. A repository on the same disk is useful for practice but does not survive loss of that disk.',
'UBU01 only, 2 GB. Optional UBU02 for a later remote repository.',[
step('1. Install restic and prepare dummy data',(p('Install restic with sudo apt install restic in update mode, record restic version, then return private.') + p('These exercises use your home directory so they do not alter a live service.'))+code('mkdir -p ~/lab/week19/source\nprintf "customer,classification\\nDemo Person,dummy\\n" > ~/lab/week19/source/records.csv\nsha256sum ~/lab/week19/source/records.csv > ~/lab/week19/original.sha256')),
step('2. Initialize an encrypted repository',code('restic -r ~/lab/week19/repository init\nrestic -r ~/lab/week19/repository backup ~/lab/week19/source\nrestic -r ~/lab/week19/repository snapshots')+(actions('Choose a unique repository password and store it in your password manager.', 'Do not put it into shell history or the evidence report.', 'Record the snapshot ID and time.') + p('The snapshot is not a Hyper-V checkpoint.'))),
step('3. Simulate file loss safely',code('mv ~/lab/week19/source/records.csv ~/lab/week19/records.simulated-loss\nls -la ~/lab/week19/source\nrestic -r ~/lab/week19/repository restore latest --target ~/lab/week19/restore')+(p('The restore target is separate from the original location. restic reconstructs the backed-up path under that target; for learner it is normally ~/lab/week19/restore/home/learner/lab/week19/source/records.csv.') + p('Find the actual restored file before comparing.'))),
step('4. Validate content, not just the success message',code('find ~/lab/week19/restore -name records.csv -type f\nsha256sum ~/lab/week19/restore/home/learner/lab/week19/source/records.csv\ncat ~/lab/week19/original.sha256\nrestic -r ~/lab/week19/repository check')+(p('The hash must match the original.') + actions('Read the restored CSV and confirm it is usable.', 'Record the restore start/end times.', 'Copy the verified restored file back into source after checking the destination.'))),
step('5. Explain the failure domains',(p('This repository and its source share UBU01’s disk and the same physical SSD. It protects the exercise against a removed file, not VM destruction, SSD failure, theft, or an administrator deleting both.') + actions('Write a real backup design with a separate device/location, protected credentials, restricted deletion, tested restores, and a retention schedule.', 'Do not claim the lab has implemented those controls.'))),
step('6. Preserve the course work',(p('Shut UBU01 down and use Hyper-V Manager → Export to a directory under C:\\CyberLab\\Exports with enough free space.') + p('An export on the same SSD is still not an off-device backup.') + actions('If an external drive is available, copy the export there and test importing a copy with a new unique VM ID on a disconnected network.', 'Never boot an imported copy with the same IP alongside the original.')))],
['Snapshot and repository check','Restored-file hash and measured recovery time','Backup design explaining shared-disk risk'],['How much data could be lost after a daily backup?','What happens if the repository password is lost?'],
'Restored file “missing”: inspect the reconstructed directory path with find. Wrong hash: check snapshot time and selected file. Repository locked: confirm no active restic process before following documented recovery; do not delete lock files blindly.',
'Build an SFTP repository on UBU02, perform another restore, and explain why two VMs on one SSD still share a physical failure domain.',
[('restic repository setup','https://restic.readthedocs.io/en/stable/030_preparing_a_new_repo.html'),('restic restore','https://restic.readthedocs.io/en/stable/050_restore.html')])

add(20,'Containers and data exposure','Assurance',
'A container shares its host kernel. An image supplies software; a container is an instance. Port publication and filesystem mounts cross boundaries. A read-only mount prevents writes through that mount but does not prevent accidental disclosure of the mounted files.',
'UBU01 + UBU02 only, private switch during all container runs. Docker runs inside UBU01, never on the Windows host.',[
step('1. Install the Ubuntu-packaged engine',(p('In UBU01 update mode, stop nginx, install docker.io, and pull the training image.') + p('This course uses Ubuntu’s packaged Docker engine; do not mix it with Docker’s separate repository packages.') + p('Do not add learner to the docker group, which would grant broad host control.'))+code('sudo apt install docker.io\nsudo systemctl enable --now docker\nsudo docker pull nginx:stable-alpine\nsudo docker image inspect nginx:stable-alpine --format \'{{index .RepoDigests 0}}\'','UBU01 • Bash, update mode')+(p('Record the returned digest.') + p('The tag can change over time.') + p('Return to private mode before running containers.') + p('Docker’s published ports can bypass expected ufw filtering; isolation and explicit bind addresses are essential.'))),
step('2. Prepare a deliberate dummy exposure',code('mkdir -p ~/lab/week20/published ~/lab/week20/private\nprintf "Public training page\\n" > ~/lab/week20/published/index.html\nprintf "DUMMY-ONLY-INTERNAL-NOTE\\n" > ~/lab/week20/published/internal.txt\nsudo docker run -d --name labweb -p 10.77.0.11:8080:80 --mount type=bind,src="$HOME/lab/week20/published",dst=/usr/share/nginx/html,readonly nginx:stable-alpine','UBU01 • Bash')+p('The bind exposes TCP 8080 only at the private guest address. The mount is read-only but deliberately includes a file that should not be served. It contains no actual secret.')),
step('3. Test the boundary from the client',code('curl -i http://10.77.0.11:8080/\ncurl -i http://10.77.0.11:8080/internal.txt','UBU02 • Bash')+(p('Both requests should succeed before remediation.') + actions('On UBU01 inspect sudo docker ps, sudo docker logs labweb, and sudo docker inspect labweb.', 'Find the port binding and mount source.'))),
step('4. Remediate and retest',code('mv ~/lab/week20/published/internal.txt ~/lab/week20/private/internal.txt','UBU01 • Bash')+(p('Repeat both HTTP requests.') + p('Public index should remain available; internal.txt should now return 404.') + p('Explain why the readonly flag alone did not solve disclosure.') + p('Preserve only the dummy example in your portfolio.'))),
step('5. Remove the workload and verify',code('sudo docker stop labweb\nsudo docker rm labweb\nsudo docker ps -a','UBU01 • Bash')+(actions('From UBU02 repeat the request with --max-time 5; it should fail.', 'Keep the image cached if repeating the lab.') + p('Ensure no container runs before reconnecting UBU01 for internet updates or dashboard management.') + p('Do not mount /, /var/run/docker.sock, or real credentials into a training container.'))),
step('6. Write a short threat model',(actions('List assets, trusted users, image supplier, published port, host mount, and two threats: unintended files served and excessive container privilege.', 'Describe controls and how you would test them.', 'Compare container isolation with a VM; neither is a reason to skip patching.')))],
['Image digest and container boundary diagram','Public success/private-file denial after correction','Container cleanup and threat model'],['Why did a read-only mount still disclose data?','How can port publication surprise firewall assumptions?'],
'Container name in use: inspect docker ps -a and remove only the prior stopped labweb. Port conflict: inspect the exact 8080 listener. Mount empty: verify the absolute source path and file permissions.',
'Inspect image layers and the configured user. Research the official image’s documented support for read-only root filesystems before attempting additional hardening.',
[('Docker port publishing','https://docs.docker.com/engine/network/port-publishing/'),('Docker bind mounts','https://docs.docker.com/engine/storage/bind-mounts/'),('Docker firewall behavior','https://docs.docker.com/engine/network/packet-filtering-firewalls/')])

add(21,'Use small scripts to make investigations repeatable','Assurance',
'Security work benefits from small, readable automation even when you do not want to be a software developer. A useful script handles bad input, states its assumptions, and produces a result someone else can verify. This week summarizes logs without changing any system.',
'UBU01 only. Work on a copy of Suricata EVE data; no live scanning.',[
step('1. Prepare a private working copy',code('mkdir -p ~/lab/week21\nsudo cp /var/log/suricata/eve.json ~/lab/week21/eve-copy.json\nsudo chown learner:learner ~/lab/week21/eve-copy.json\nchmod 600 ~/lab/week21/eve-copy.json\nsha256sum ~/lab/week21/eve-copy.json')+(actions('If the source is absent, repeat Week 15’s harmless ping test first.', 'Never run a parsing experiment on the only copy of evidence.'))),
step('2. Create the summarizer',p('Use nano ~/lab/week21/summarize.py. Enter this complete script:')+code('import json\nimport sys\nfrom collections import Counter\n\ncounts = Counter()\nbad = 0\nwith open(sys.argv[1], encoding="utf-8") as source:\n    for line in source:\n        try:\n            event = json.loads(line)\n            if not isinstance(event, dict):\n                bad += 1\n                continue\n            alert = event.get("alert")\n            if event.get("event_type") == "alert" and isinstance(alert, dict):\n                signature = str(alert.get("signature", "unknown"))\n                counts[signature] += 1\n        except json.JSONDecodeError:\n            bad += 1\nfor signature, count in sorted(counts.items()):\n    print(f"{count}\\t{signature}")\nprint(f"Malformed or non-object lines: {bad}", file=sys.stderr)','UBU01 • summarize.py')),
step('3. Run and cross-check',code('python3 ~/lab/week21/summarize.py ~/lab/week21/eve-copy.json\njq -r \'select(.event_type=="alert") | .alert.signature\' ~/lab/week21/eve-copy.json | sort | uniq -c')+(actions('Compare counts from two independent methods.', 'Read the script aloud: file input, JSON parsing, filtering, counting, output.') + p('A count of zero is possible and meaningful; it is not necessarily a program failure.'))),
step('4. Test malformed input safely',code('cp ~/lab/week21/eve-copy.json ~/lab/week21/test-bad.json\nprintf "not-json\\n" >> ~/lab/week21/test-bad.json\npython3 ~/lab/week21/summarize.py ~/lab/week21/test-bad.json')+p('Alert counts should match the original and malformed count should increase by one. A real evidence pipeline should preserve malformed records for investigation; this teaching script only counts them.')),
step('5. Track a small change',code('cd ~/lab/week21\ngit init\ngit config user.name "CyberLab Learner"\ngit config user.email "learner@example.test"\nprintf "*.json\\n" > .gitignore\ngit add summarize.py .gitignore\ngit commit -m "Add local alert summarizer"\ngit status')+(p('Use this local repository only.') + p('Commit the script and ignore raw JSON so event data is not accidentally included. A .gitignore entry does not remove files already committed; inspect git ls-files before any future public upload.')))],
['Script with explained assumptions','Independent count comparison','Malformed-input test and clean Git file list'],['What does the script silently leave out?','Why is excluding raw evidence from source control useful?'],
'File not found: use the exact path and check pwd/ls. JSON parse errors in jq after adding bad input are expected; use the clean source for the cross-check. Do not “fix” the original evidence by editing it.',
'Add a --help option or a source-IP grouping, then define expected results before implementing it. Keep the scope small.',
[('Python JSON module','https://docs.python.org/3/library/json.html'),('Git tutorial','https://git-scm.com/docs/gittutorial')])

add(22,'Rebuild, document risk, and pass the local capstone','Assessment',
'Professional competence includes explaining choices, accepting limits, and restoring a working system from documented steps. This week joins the layers you have practiced. Documentation is tested when someone else uses it.',
'Use staged profiles: Linux 4 GB, identity 8 GB, monitoring 10 GB. This is also the scheduled catch-up week before cloud.',[
step('1. Select a business scenario',(actions('Use a fictional small training center with an internal web page, two staff roles, dummy records, and a requirement to detect unauthorized file changes.', 'Write five requirements: private access, least privilege, encrypted transport, observable changes, and recoverable data.') + p('State a lab recovery target of 30 minutes for the dummy file and explain it is an exercise target, not a measured guarantee yet.'))),
step('2. Produce the architecture',(p('Draw the host, private switch, every VM/IP, each service, allowed ports, and data flow.') + actions('Add a second diagram showing which machines are powered on together.', 'Mark the temporary dashboard management path and the conditions for removing it.') + p('Include the Windows replay limitation.'))),
step('3. Run acceptance tests',(p('Demonstrate from saved instructions: UBU02 reaches nginx; SSH password login is denied while key login works; TLS is verified with the lab trust file; a file change produces FIM evidence; a sensor ping reaches central monitoring; a backup restore matches its original hash.') + p('Renew the Week 10 lab certificate if it expired.') + p('Perform tests in separate power profiles.'))),
step('4. Diagnose one unknown fault',(p('Your mentor chooses a single fault from the mentor guide and records the original setting privately. You get 45 minutes to state the symptom, collect evidence, form a hypothesis, repair one cause, and rerun the acceptance test. No random reinstalling.') + p('If you cannot solve it, explain what you ruled out and what evidence you need next.'))),
step('5. Write a five-item risk register',(p('Include weak points you actually have: one physical SSD, intermittent central monitoring, evaluation-license lifetime, temporary dual-homed management, and limited network visibility.') + actions('For each record likelihood/impact in plain language, current control, remaining risk, owner, next action, and review date.', 'Do not disguise a known limitation as a completed control.'))),
step('6. Hold a readiness review',(p('Present for 15 minutes, then answer mentor questions for 15 minutes. Pass requires a correct network boundary, observed positive and negative tests, one successful restore, and at least 8/10 on the rubric.') + p('If a required gate fails, use the remaining week for repair and repeat; postpone cloud until the foundation is sound.')))],
['Architecture and power profiles','Six acceptance tests with evidence','Risk register and local capstone score'],['Which control would you improve first with more RAM or budget?','What would fail if the host SSD died?'],
'Old evidence does not prove the current state. Re-run a small fresh test when configuration or versions changed. If multiple faults appear, return to a known baseline and document the divergence before continuing.',
'Ask another person to follow one runbook without verbal help. Record unclear steps and improve the guide.',
[('NIST Cybersecurity Framework','https://www.nist.gov/cyberframework')])

add(23,'Cloud foundations, access, and cost controls','Cloud',
'Cloud changes who operates each layer; it does not remove your responsibility for identity, data, configuration, and monitoring. Azure has a management plane for resources and separate data-plane permissions. A budget alert is not a hard spending cap.',
'Windows host browser only. Local VMs off. Default cloud track is Azure; use an authorized sandbox or your own dedicated learning subscription.',[
step('1. Choose the cloud boundary',(p('Working solo?') + p('Use separate administrator and learner sessions.') + p('You handle tasks labeled “mentor” using the administrator identity; run exercises as the restricted learner.') + actions('Check credit eligibility, expiry, prices and billing terms before using a personal Azure account.', 'If you prefer no billing exposure, skip deployment, repeat the Week 22 capstone and document the proposed cloud controls on paper.') + p('The administrator signs in to Azure and creates a dedicated resource group rg-cyberlab-learner in an agreed region.') + actions('Use a separate learner identity protected by MFA.', 'Assign Contributor only at this resource group for creation labs; the administrator retains role-assignment and billing administration.', 'Do not use an employer production subscription or share the subscription owner password.', 'Record tenant, subscription, group, and region privately.'))),
step('2. Inspect your effective access',(actions('Learner: sign in at portal.azure.com → Directory + subscriptions and select the intended tenant/subscription.', 'Open Resource groups → rg-cyberlab-learner → Access control (IAM) → View my access.', 'Record the scope and role.') + p('Contributor can manage resources but cannot generally assign roles.') + p('Do not attempt changes outside the group.'))),
step('3. Set a budget before resources',(actions('Administrator: open Cost Management at the subscription or supported resource-group scope → Budgets → Add.', 'Choose an agreed monthly amount in the subscription’s billing currency, start/end dates, and actual-cost alerts at 50%, 80%, and 100% to the person responsible for billing.') + check('Verify recipients and save.') + actions('Check the Azure pricing calculator for a small Linux VM, managed disk, public IPv4, and minimal storage in the selected region.', 'Record an estimate, not a promise of free service.') + p('Budget evaluation and cost reporting can be delayed; they do not stop resource creation.'))),
step('4. Create a safe management event',(actions('Open the resource group → Tags.', 'Add Course=CyberLab and Owner=Learner, then Save.', 'Open Activity log, set the recent time range, and locate the write operation.', 'Expand it and identify actor, operation, status, timestamp, and correlation ID.', 'Export the event privately.') + p('This records a management action, not every data read inside a workload.'))),
step('5. Build the cloud worksheet',(actions('Write the shared responsibility for five layers: physical hardware, guest OS patching, identity, network rules, and data access.', 'Record the maximum agreed lab duration, who monitors spend, cleanup owner, and the exact resource-group name.', 'Set a calendar reminder yourself before deploying the next lab; do not rely on memory.'))),
step('6. Gate for paid resource creation',(p('Review and record the selected subscription, role scope, budget settings, region, and calculator estimate.') + p('Continue only after verifying access, estimating cost, setting budget alerts and scheduling cleanup; if working with a mentor, review those checks together.') + p('If cloud access is not ready, repeat the Week 22 capstone or local TLS lab; do not create a personal paid account just to stay on schedule.')))],
['Scoped learner access and MFA confirmation','Budget/estimate/cleanup worksheet','An attributable cloud management event'],['Why is Contributor not the same as Owner?','What does the budget fail to prevent?'],
'Cannot create a budget: the learner identity may lack billing access. If studying solo, use your authorized administrator account to configure the budget, then switch back to your learner identity. In a managed sandbox, ask the billing administrator. If neither option is available, defer paid deployment. Wrong directory: switch tenant/subscription before diagnosing permissions. A quota or regional SKU restriction is not solved by choosing a much more expensive machine.',
'Compare this resource-group boundary with an AWS account/IAM boundary at a conceptual level; do not deploy a second cloud.',
[('Azure budget tutorial','https://learn.microsoft.com/en-us/azure/cost-management-billing/costs/tutorial-acm-create-budgets'),('Azure shared responsibility','https://learn.microsoft.com/en-us/azure/security/fundamentals/shared-responsibility'),('Azure pricing calculator','https://azure.microsoft.com/en-us/pricing/calculator/')])

add(24,'Deploy and secure a small cloud workload','Cloud',
'A network security group (NSG) controls network traffic at the cloud boundary; a guest firewall controls traffic in the OS. SSH proves access to the machine, not necessarily to the application. This lab exposes SSH only to your current public IP and carries web traffic through a tunnel.',
'One mentor-approved Azure Ubuntu 24.04 VM. No local VMs. All resource creation stays in rg-cyberlab-learner.',[
step('1. Create the VM with explicit choices',p('In the Azure portal, open <strong>Virtual machines → Create → Azure virtual machine</strong>.')+
p('<strong>Basics</strong> — use the scope and budget you recorded in Week 23.')+
settings(('Subscription / resource group / region','Use the approved lab subscription, <code>rg-cyberlab-learner</code>, and approved region.'),('Virtual machine name','<code>az-ubu01</code>'),('Image','Ubuntu Server 24.04 LTS, x64 Gen2'),('Size','A small approved size, such as 1–2 vCPU if available.'),('Authentication','SSH public key'),('Username','<code>learner</code>'),('SSH key source','Generate a new key pair'),('Public inbound ports','None initially'))+
note('<strong>If quota blocks the selected size:</strong> stop and review capacity and cost. Do not select an unreviewed larger size.')+
actions('<strong>Disks:</strong> select a standard managed disk.','Review the remaining tabs. Leave optional paid monitoring and security trials off.','Open <strong>Review + create</strong>. Compare the displayed cost estimate with your approved budget. If it does not fit, stop before creating the VM.','Select <strong>Create</strong>. When prompted, download the private key into your private credentials folder. Keep it out of evidence, screenshots and Git.')),
step('2. Restrict the one inbound rule',p('Open <strong>az-ubu01 → Networking / Network settings</strong>, select its network security group, and add an inbound rule.')+
settings(('Source','IP Addresses: your current public IPv4 address with <code>/32</code>. Use <strong>My IP</strong> if offered and verify it is your current connection.'),('Source port','<code>*</code>'),('Destination port','<code>22</code>'),('Protocol / action','TCP / Allow'),('Priority','1000'),('Name','<code>Allow-SSH-MyIP</code>'))+
p('Save the rule. Leave the default deny for Internet traffic in place.')+
check('Review effective rules: no broader SSH allow rule should precede yours. Do not add SSH or web access from 0.0.0.0/0.')),
step('3. Connect and patch',(actions('Use the VM Connect → Native SSH instructions with the downloaded key and current VM public IP.', 'In host PowerShell:'))+code('ssh -i "C:\\CyberLab\\Private\\REPLACE_KEY.pem" learner@REPLACE_VM_PUBLIC_IP','HOST • PowerShell; replace both tokens')+(check('Verify the host key through an independent portal Run command reading /etc/ssh/ssh_host_ed25519_key.pub with ssh-keygen -lf before accepting the fingerprint.') + p('If Windows OpenSSH rejects key permissions, use a private user-owned directory and restrict that file through Properties → Security; never publish the key.'))),
step('4. Configure the application and guest boundary',code('sudo apt update\nsudo apt upgrade\nsudo apt install nginx ufw\nsudo ufw default deny incoming\nsudo ufw default allow outgoing\nsudo ufw allow from REPLACE_YOUR_PUBLIC_IP to any port 22 proto tcp\nsudo ufw enable\nsudo systemctl enable --now nginx\ncurl -I http://127.0.0.1','AZ-UBU01 • Bash; replace source IP before executing')+(actions('Keep your current SSH session open.', 'Open a second session to prove the allow rule before closing the first.', 'If your public IP changes, update both NSG and guest rule through a verified management path; do not widen to everyone.'))),
step('5. Test through a tunnel',code('ssh -i "C:\\CyberLab\\Private\\REPLACE_KEY.pem" -N -L 8085:127.0.0.1:80 learner@REPLACE_VM_PUBLIC_IP','HOST • second PowerShell window')+(p('Open http://localhost:8085.') + p('It should show nginx over the encrypted SSH tunnel.') + check('Direct http://VM_PUBLIC_IP should fail because no public HTTP rule exists.') + p('This is not an HTTPS certificate deployment; the tunnel provides transport encryption to the guest.') + p('Save both positive and negative results.'))),
step('6. Stop costs deliberately',(actions('Close the tunnel.', 'In the portal stop the VM and wait for Stopped (deallocated), not just an OS shutdown.', 'Set a same-day auto-shutdown time if retaining it briefly, accounting for the displayed timezone.') + p('Disks and public IP resources may still incur charges.') + actions('For this course, export evidence and delete the lab resource group at the end of the session unless the mentor explicitly chooses retention.', 'Type the exact group name and confirm only its listed lab resources are included.') + check('Verify the group and resources disappear, then review Cost Analysis later for delayed charges.') + p('Recreate the group for Week 25.')))],
['NSG and guest firewall scope','Tunnel success and direct-HTTP denial','Deallocation/deletion proof and cost review'],['How do NSG and guest firewall interact?','Why does stopping a VM not guarantee zero cost?'],
'SSH timeout: check public IP, source /32, NSG rule priority, VM power state, and guest rule. Key rejection: verify user/key pair and permissions. Use portal Run command for a locked-out guest only within the mentor-approved lab group.',
'Record the equivalent Azure CLI commands from portal documentation and explain them; do not deploy a second VM just to demonstrate another interface.',
[('Azure Linux VM creation','https://learn.microsoft.com/en-us/azure/virtual-machines/linux/quick-create-portal'),('Azure NSGs','https://learn.microsoft.com/en-us/azure/virtual-network/network-security-groups-overview'),('VM states and billing','https://learn.microsoft.com/en-us/azure/virtual-machines/states-billing')])

add(25,'Cloud data access and audit boundaries','Cloud',
'Control-plane Reader lets you see a resource; it does not automatically let you read its blobs. Data access needs a data role. Anonymous access, shared keys, and identity-based access have different control and audit properties. An Activity log is not a substitute for storage data logs.',
'Host browser only. One small Azure storage account with dummy data in the dedicated lab resource group. No VM required.',[
step('1. Create private-by-default storage',(p('Mentor recreates rg-cyberlab-learner if deleted.') + actions('Create a Storage account in the agreed region, unique lowercase alphanumeric name, Standard performance, locally redundant storage, general-purpose v2.', 'On Advanced/Security settings require secure transfer, minimum TLS 1.2, disable anonymous blob access, and disable storage account key access for this identity-only exercise.', 'On Networking permit the selected current client public IP only.') + p('Portal labels can change; verify the final properties after creation.') + p('Do not add private endpoints or paid Defender trials for this core lab.'))),
step('2. Create and upload dummy data as the instructor',(p('The mentor assigns their own identity Storage Blob Data Contributor at this storage account if needed.') + p('Open Data storage → Containers → create evidence with private access.') + p('Upload a tiny text file lab-note.txt containing only “CyberLab dummy data.” Use Microsoft Entra user-account authentication in the portal, not account keys. Role propagation can take several minutes.'))),
step('3. Prove control-plane-only denial',(p('For this test, the learner should have only Reader at the lab resource group and no inherited data role.') + p('Mentor temporarily removes the learner’s prior Contributor assignment and assigns Reader. Learner signs out/in to refresh access, opens the storage account, and attempts to read the container through Entra authentication.') + check('Expect data-access denial. Confirm the storage firewall permits the current client IP first; a network block would invalidate this role test.'))),
step('4. Grant the minimum read role',(actions('Mentor opens the evidence container → Access control (IAM) → Add role assignment → Storage Blob Data Reader → select learner → Review + assign.', 'Keep resource-group Reader for portal navigation.', 'After propagation, learner refreshes and reads lab-note.txt.') + p('Try uploading a second dummy file; it should be denied.') + p('Do not “fix” this by granting Owner or enabling shared keys.'))),
step('5. Test anonymous access and inspect audit coverage',(p('Copy the blob URL and request it in a private browser session without sign-in.') + p('It must not reveal the content.') + actions('Inspect Activity log for role/configuration writes and identify who performed them.', 'Explain that blob reads require separately enabled storage resource logging for a read audit; absence from Activity log is expected.') + p('Optional within an approved ingestion budget: on the Blob service Diagnostic settings send StorageRead/Write/Delete logs to a small Log Analytics workspace, repeat the read, and inspect StorageBlobLogs for operation, status, authentication type, and requester fields.') + p('Do not enable paid logging without the mentor’s agreed limit.'))),
step('6. Remove access and clean up',(p('Mentor removes the container data-role assignment; after refresh/propagation learner’s read should fail again.') + actions('Record that issued tokens/caches can delay a clean test.', 'Export sanitized evidence and delete the whole lab resource group after verifying its contents.') + check('Confirm storage and any optional workspace are gone.') + p('Review delayed cost records.')))],
['Reader-only denial, blob-reader success, write denial','Anonymous-read denial','Audit coverage explanation and cleanup'],['Why is a 403 not enough to prove an IAM policy worked?','Which log would you need to investigate a blob read?'],
'Portal data access fails despite role: check tenant, selected auth mode, inherited roles, role scope, propagation, and client-IP firewall. A changing ISP public IP can invalidate a network test without changing IAM.',
'Create a control-plane/data-plane permission matrix and explain how a managed identity would replace a stored application secret.',
[('Blob data roles','https://learn.microsoft.com/en-us/azure/storage/blobs/assign-azure-role-data-access'),('Azure Activity log','https://learn.microsoft.com/en-us/azure/azure-monitor/platform/activity-log'),('Blob monitoring','https://learn.microsoft.com/en-us/azure/storage/blobs/monitor-blob-storage')])

add(26,'Demonstrate your security practice','Assessment',
'A professional portfolio shows decisions, evidence, limitations, and reproducible results. It does not need real customer data or dramatic attack claims. Your final assessment asks you to connect the layers and explain how you know a control works.',
'Local staged profiles only; cloud evidence from Weeks 23–25. Cloud resources should already be deleted.',[
step('1. Assemble six small portfolio artifacts',(p('Create a sanitized portfolio folder. Use the templates to assemble these six artifacts:') + ul('Architecture and VM power plan','Linux and Windows access-control tests','Two detection rule cards with test evidence','Incident report','Backup restore report','Cloud IAM and network report with cleanup evidence') + p('Include dates, versions, and known limitations in every artifact.'))),
step('2. Re-run one end-to-end scenario',(p('Mentor selects either a file-change case or the benign Suricata ping case. State expected behavior first.') + actions('Generate the event, find it locally, trace it centrally, decide its significance, and document a recovery or tuning action.', 'Use fresh timestamps.') + p('A replay-only Windows exercise must be labeled replay.'))),
step('3. Give a 20-minute technical demonstration',(p('Spend 4 minutes on architecture, 6 on the live local scenario, 4 on identity/access tests, 3 on recovery, and 3 on cloud lessons.') + p('Keep a backup of screenshots/output in case of hardware trouble, and clearly distinguish live results from recorded ones.'))),
step('4. Answer the oral assessment',(p('Explain: a browser-to-server request across layers; authentication versus authorization; when a sensor cannot see traffic; the source-to-alert pipeline; one false positive; the difference between containment and recovery; how to prove a restore; and cloud management versus data access.') + p('It is acceptable to say “I do not know; here is how I would verify it.”'))),
step('5. Receive a specific readiness decision',(p('Mentor scores the final work with the rubric. Pass requires at least 8/10, no unresolved boundary/secrets issue, a working detection with positive and negative evidence, a verified restore, and a clear explanation of replay/coverage limits.') + p('Record strengths, three improvement areas, and one next role to explore: infrastructure security, detection engineering, cloud security, vulnerability management, or incident response.') + p('The course completion is not a professional certification.'))),
step('6. Plan the next 90 days',(p('Choose one specialization based on the work he enjoyed, not on tool popularity.') + p('Schedule one repeatable project, one reading track, and one monthly mentor review. Consider targeted paid practice only for a demonstrated gap.') + actions('Before publishing any portfolio, remove credentials, tokens, private keys, raw identifiers, and third-party restricted assets.', 'Keep private originals and publish only reviewed copies.')))],
['Six reviewed portfolio artifacts','Fresh scenario and final score','A focused next-90-days plan'],['Which evidence would convince another engineer your control works?','Which parts of your environment remain untested?'],
'A demo fails: state the actual failure, locate its layer, and explain recovery. Do not substitute an old screenshot without labeling it. Honest troubleshooting is part of the assessment.',
'Teach one Week 1–6 lab to another beginner and record where your explanations fail. Feed those changes into the next course edition.',
[('NICE workforce framework','https://www.nist.gov/itl/applied-cybersecurity/nice/nice-framework-resource-center')])
